window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[173]={"id":"173","numero":173,"titre":"Zoonoses","objectifs":[{"id":"173-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une zoonose","contenu":"<div class=\"notion-course\"><p>Une <span>zoonose</span> est une <span>maladie infectieuse transmise de l'animal à l'homme</span>. L'agent pathogène peut être de nature <span>bactérienne</span>, virale ou parasitaire — d'où la <span>classification</span> en trois familles étiologiques.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Zoonoses du programme EDN</th></tr></thead>\n        <tbody>\n          <tr><td><span>Bactériennes</span></td><td><span><span class=\"nc-purple_bg\">Fièvre Q</span></span> ; <span><span class=\"nc-pink nc-bold\">pasteurellose</span></span> ; <span><span class=\"nc-purple_bg\">maladie des griffes du chat</span></span> ; <span><span class=\"nc-pink nc-bold\">borréliose de Lyme</span></span></td></tr>\n          <tr><td><span>Virales</span></td><td><span>Rage</span></td></tr>\n          <tr><td><span>Parasitaires</span></td><td><span><span class=\"nc-orange_bg\">Toxoplasmose</span></span> ; <span>échinococcoses</span> (hydatique et alvéolaire) ; <span>leishmaniose</span></td></tr>\n        </tbody>\n      </table>\n      <p>Trois grands <strong>modes de transmission</strong> structurent l'item :</p>\n      <ul>\n        <li><strong>Transmission directe par un animal</strong> — <span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>, <span>léchage</span>, <span>contact</span>, <span class=\"nc-brown_bg\">voie digestive</span> ou inhalée.</li>\n        <li><strong>Transmission par un vecteur</strong> — un <span>arthropode</span> (<span><span class=\"nc-orange nc-bold\">tique</span></span>, <span><span class=\"nc-yellow_bg nc-bold\">phlébotome</span></span>) fait le passage de l'animal réservoir à l'homme.</li>\n        <li><strong>Pathologie d'inoculation</strong> — pénétration de l'agent à travers la peau ou <span>les</span> muqueuses.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-2","rang":"B","rubrique":"Étiologies","titre":"Citer les principales étiologies bactériennes, virales et parasitaires des zoonoses","contenu":"<div class=\"notion-course\"><p><span>Les</span> zoonoses du programme se répartissent en trois familles selon la nature de l'agent pathogène.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Zoonose</th><th>Agent</th></tr></thead>\n        <tbody>\n          <tr><td><span>Bactérienne</span></td><td><span>Fièvre</span> Q</td><td><span>Coxiella burnetii</span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td>Pasteurellose</td><td><span><span class=\"nc-purple nc-bold\">Pasteurella multocida</span></span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td><span class=\"nc-purple_bg\">Maladie des griffes du chat</span></td><td><span><span class=\"nc-purple nc-bold\">Bartonella henselae</span></span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td>Borréliose de Lyme</td><td><span>Borrelia</span> (<span>spirochète</span>)</td></tr>\n          <tr><td><span>Virale</span></td><td>Rage</td><td><span>Lyssavirus</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td><span class=\"nc-orange_bg\">Toxoplasmose</span></td><td><span>Toxoplasma gondii</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td>Échinococcoses</td><td><span><span class=\"nc-purple nc-bold\">Echinococcus granulosus</span></span> ; <span>E. multilocularis</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td>Leishmaniose</td><td><span>Leishmania</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🔁 <strong>Mnémo — <span>les</span> 7 zoonoses directement transmises par un animal</strong> : « Fabrice Putain T'es Relou la ChattE » → <strong>F</strong>ièvre Q, <strong><span class=\"nc-pink nc-bold\">P</span></strong><span class=\"nc-pink nc-bold\">asteurellose</span>, <strong><span class=\"nc-orange_bg\">T</span></strong><span class=\"nc-orange_bg\">oxoplasmose</span>, <strong><span class=\"nc-green_bg\">R</span></strong><span class=\"nc-green_bg\">age</span>, <span class=\"nc-purple_bg\">maladie des griffes du </span><strong><span class=\"nc-purple_bg\">chat</span></strong>, <strong><span class=\"nc-orange_bg\">é</span></strong><span class=\"nc-orange_bg\">chinococcose hydatique</span> et alvéolaire.</div>\n      <p><strong>Bactéries potentiellement transmises par <span>morsure humaine</span></strong> : <span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, <span>H. influenzae</span>, <span>Eikenella corrodens</span>, <span><span class=\"nc-purple nc-bold\">anaérobies</span></span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes lignes de l’épidémiologie des principales zoonoses","contenu":"<div class=\"notion-course\"><p>L'<span>épidémiologie</span> des zoonoses se lit sur trois axes : le <strong>réservoir animal</strong>, le <strong>mode de transmission</strong> et la <strong>répartition géographique</strong>.</p>\n      <table>\n        <thead><tr><th>Zoonose</th><th>Réservoir</th><th>Transmission</th></tr></thead>\n        <tbody>\n          <tr><td>Borréliose de Lyme</td><td><span><span class=\"nc-orange nc-bold\">Tiques</span> Ixodes</span></td><td>Vecteur (<span><span class=\"nc-red_bg\">piqûre de tique</span></span>)</td></tr>\n          <tr><td>Griffes du chat</td><td><span>Chat</span> (chaton)</td><td>Inoculation (<span><span class=\"nc-blue_bg\">griffure</span></span>, <span><span class=\"nc-blue_bg\">morsure</span></span>)</td></tr>\n          <tr><td>Pasteurellose</td><td><span>Chat</span>, <span><span class=\"nc-green_bg\">chien</span></span>, <span><span class=\"nc-green_bg\">oiseaux</span></span></td><td>Inoculation (<span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>)</td></tr>\n          <tr><td><span class=\"nc-orange_bg\">Toxoplasmose</span></td><td><span>Chat</span>, <span>ruminants</span>, <span><span class=\"nc-green_bg\">porcins</span></span></td><td>Directe (litière, <span class=\"nc-red nc-bold\">viande mal cuite</span>)</td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Fièvre</span></span><span class=\"nc-purple_bg\"> Q</span></td><td><span><span class=\"nc-orange_bg\">Bovins</span></span>, <span><span class=\"nc-orange_bg\">ovins</span></span>, <span><span class=\"nc-orange_bg\">caprins</span></span></td><td>Directe (<span class=\"nc-red nc-bold\">lait cru</span>, aérosols) ou vecteur (<span>tiques</span>)</td></tr>\n          <tr><td><span class=\"nc-green_bg\">Rage</span></td><td><span><span class=\"nc-green_bg\">Canidés</span></span>, <span><span class=\"nc-green_bg\">renard</span></span>, <span>chauve-souris</span></td><td>Directe (<span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>, <span>léchage</span>)</td></tr>\n          <tr><td>Échinococcoses</td><td><span><span class=\"nc-red nc-bold\">Chien</span></span> (hydatique) ; <span>renard</span> (alvéolaire)</td><td>Directe ou indirecte (aliments souillés)</td></tr>\n          <tr><td><span class=\"nc-pink nc-bold\">Leishmaniose</span></td><td><span>Chien</span>, <span>rongeurs</span></td><td>Vecteur (<span>phlébotome</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🎯 <strong><span>Les</span> 3 zoonoses transmises par un vecteur</strong> : <span class=\"nc-orange_bg\">leishmaniose</span> (<span><span class=\"nc-yellow_bg nc-bold\">phlébotome</span></span>), <span class=\"nc-purple_bg\">borréliose de Lyme</span> (<span><span class=\"nc-orange nc-bold\">tique</span> Ixodes</span>), <span><span class=\"nc-purple_bg\">fièvre</span></span><span class=\"nc-purple_bg\"> Q</span> (<span class=\"nc-orange nc-bold\">tiques</span>).</div>\n      <div class=\"callout callout-info\">🎯 <strong><span>Les</span> 4 zoonoses les plus fréquentes en <span class=\"nc-green_bg\">France</span> métropolitaine</strong> : <span class=\"nc-purple_bg\">borréliose de Lyme</span>, <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, <span class=\"nc-pink nc-bold\">pasteurellose</span>, <span class=\"nc-orange_bg\">toxoplasmose</span>.</div>\n      <p><span>Les</span> <strong>4 pathologies d'inoculation</strong> (transmission à travers la peau et les muqueuses) : <span class=\"nc-pink nc-bold\">borréliose de Lyme</span>, <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, <span class=\"nc-pink nc-bold\">pasteurellose</span>, <span class=\"nc-pink nc-bold\">leishmaniose</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Précision sur le cycle de Lyme : les <span class=\"nc-orange nc-bold\">tiques</span> Ixodes sont les vecteurs ; les réservoirs incluent petits <span class=\"nc-yellow_bg nc-bold\">mammifères</span> et <span class=\"nc-green_bg\">oiseaux</span>. Pour la <span class=\"nc-purple_bg\">fièvre Q</span> humaine, l’inhalation d’aérosols <span class=\"nc-red nc-bold\">contaminés</span> issus d’animaux d’élevage est majeure ; ne pas la présenter comme une infection habituellement transmise par <span class=\"nc-red_bg\">piqûre de tique</span>.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-4","rang":"A","rubrique":"Définition","titre":"Maladie des griffes du chat : connaître les généralités","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-purple_bg\">maladie des griffes du chat</span></span> — aussi appelée <span><span class=\"nc-yellow_bg\">lymphoréticulose bénigne d'inoculation</span></span> — est une zoonose <span>bactérienne</span> bénigne d'inoculation.</p>\n      <table>\n        <tbody>\n          <tr><td>Agent</td><td><span><span class=\"nc-purple_bg\">Bartonella henselae</span></span> — bactérie <span>intracellulaire</span>, non visible à la <span>coloration de Gram</span> (donc <strong>pas d'<span>hémocultures</span></strong>)</td></tr>\n          <tr><td>Réservoir</td><td>Le <strong><span>chat</span></strong>, surtout le <span>chaton</span> et le jeune chat</td></tr>\n          <tr><td><span>Terrain</span></td><td>Surtout l'<strong>enfant</strong> et le <strong>jeune adulte</strong></td></tr>\n          <tr><td>Incubation</td><td><span>2 à <span class=\"nc-pink nc-bold\">3 semaines</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Physiopathologie</span></strong> en quatre temps :</p>\n      <ol>\n        <li><span>Bactériémie</span> asymptomatique chez le chat, qui contamine ses griffes en se grattant des zones excoriées.</li>\n        <li>Transmission à l'homme : <span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>, plus rarement <span class=\"nc-blue_bg\">léchage de plaie</span> ou piqûre de puces du chat.</li>\n        <li>Multiplication de la bactérie dans le <span>ganglion relais</span> du territoire de <span>drainage</span> lymphatique.</li>\n        <li><span><span class=\"nc-yellow_bg nc-bold\">Adénopathie</span> inflammatoire</span> : <span class=\"nc-pink nc-bold\">granulome épithélioïde sans </span><span><span class=\"nc-pink nc-bold\">nécrose</span></span><span class=\"nc-pink nc-bold\"> caséeuse</span>, <span class=\"nc-pink nc-bold\">hyperplasie folliculaire</span>, <span class=\"nc-pink nc-bold\">micro-</span><span><span class=\"nc-pink nc-bold\">abcès</span></span>.</li>\n      </ol><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Bartonella est une bactérie difficile à cultiver ; la faible sensibilité des techniques usuelles oriente vers <span class=\"nc-yellow_bg nc-bold\">sérologie</span>/PCR selon contexte. La visibilité au Gram n’est pas le critère qui décide à elle seule si une culture est réalisable.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-5","rang":"A","rubrique":"Diagnostic positif","titre":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","contenu":"<div class=\"notion-course\"><p>Le diagnostic de la <span class=\"nc-purple_bg\">maladie des griffes du chat</span> associe une <strong>présentation clinique évocatrice</strong> et une <strong>confirmation microbiologique</strong>.</p>\n      <p><strong>Présentation clinique</strong></p>\n      <ul>\n        <li><span>Lésion primaire d'inoculation</span> (<span>50 %</span> des cas) : trace de <span class=\"nc-blue_bg\">morsure</span> ou de <span class=\"nc-blue_bg\">griffure</span>.</li>\n        <li><span>Signes généraux discrets</span> (<span>50 %</span>) : <span><span class=\"nc-blue_bg\">céphalées</span></span>, <span><span class=\"nc-blue_bg\">asthénie</span></span>, <span class=\"nc-blue_bg\">fébricule</span>, <span><span class=\"nc-blue_bg\">douleurs abdominales</span></span>.</li>\n        <li><span><span class=\"nc-yellow_bg nc-bold\">Lésion érythémateuse papuleuse</span></span> précédant l'<span><span class=\"nc-yellow_bg nc-bold\">adénopathie</span></span> (<span>50 %</span>), sur le territoire lymphatique de la <span>lésion</span> cutanée.</li>\n        <li><span><span class=\"nc-yellow_bg nc-bold\">Adénopathie</span></span> du ganglion relais : <span class=\"nc-pink nc-bold\">unique</span> (<span>50 %</span>) ou <span class=\"nc-pink nc-bold\">multiple</span> sur un seul territoire unilatéral (<strong>cervical</strong>, <strong>axillaire</strong>, épitrochléen, inguinal) ; souvent <span class=\"nc-pink nc-bold\">volumineuse</span>, <span class=\"nc-blue_bg\">ferme</span>, <span class=\"nc-blue_bg\">mobile</span>, <span><span class=\"nc-red_bg\">inflammatoire</span></span><span class=\"nc-red_bg\">, sensible,</span> <span class=\"nc-pink nc-bold\">parfois en voie de</span> <span class=\"nc-pink nc-bold\">fistulisation</span>.</li>\n      </ul>\n      <p><strong>Formes cliniques particulières</strong></p>\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Syndrome oculo-glandulaire de</span> <span class=\"nc-orange_bg nc-bold\">Parinaud</span></span> — forme ophtalmique (<span>10 %</span>), surtout chez l'<strong><span class=\"nc-pink nc-bold\">enfant</span></strong> : <span class=\"nc-blue_bg\">conjonctivite</span> + <span><span class=\"nc-blue_bg\">adénopathie</span></span> prétragienne.</li>\n        <li><span class=\"nc-orange_bg\">Endocardites à </span><span><span class=\"nc-orange_bg\">hémocultures</span></span><span class=\"nc-orange_bg\"> négatives</span> — rares.</li>\n      </ul>\n      <table>\n        <tbody>\n          <tr><td>Confirmation</td><td><span><span class=\"nc-yellow_bg nc-bold\">Sérologie</span></span> en 1ʳᵉ intention (faible sensibilité — une <span><span class=\"nc-yellow_bg nc-bold\">sérologie</span></span> <span class=\"nc-red nc-bold\">négative</span> n'élimine pas le diagnostic) ; en cas de doute : <span><span class=\"nc-blue_bg\">PCR spécifique</span></span> sur <span>exérèse</span> ou <span>biopsie</span> ganglionnaire (diagnostic de certitude), <span><span class=\"nc-blue_bg\">histologie</span></span> montrant un <span class=\"nc-pink nc-bold\">granulome épithélioïde sans </span><span><span class=\"nc-pink nc-bold\">nécrose</span></span><span class=\"nc-pink nc-bold\"> caséeuse</span> (forte présomption)</td></tr>\n          <tr><td>Traitement</td><td><span><span class=\"nc-pink_bg\">Azithromycine</span></span> pendant <span><span class=\"nc-pink nc-bold\">5 jours</span></span> — <span>antibiothérapie</span> discutée, l'<span>évolution</span> étant spontanément favorable</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmission de la maladie de Lyme","contenu":"<div class=\"notion-course\"><p>La <span>borréliose de Lyme</span> est la zoonose à vecteur la plus fréquente en France métropolitaine.</p>\n      <table>\n        <tbody>\n          <tr><td>Agents</td><td>Trois espèces du genre <span>Borrelia</span> — <span>B. burgdorferi</span>, <span><span class=\"nc-purple_bg\">B. garinii</span></span>, <span><span class=\"nc-purple_bg\">B. afzelii</span></span> — de la famille des <span>spirochètes</span></td></tr>\n          <tr><td>Vecteur</td><td><span class=\"nc-purple_bg\">Piqûre de </span><span><span class=\"nc-purple_bg\">tique du genre Ixodes</span></span> : la bactérie est inoculée par régurgitation au décours d'un repas sanguin</td></tr>\n          <tr><td><span>Terrain</span></td><td>Exposition lors de promenades en forêt, de travaux agricoles et forestiers</td></tr>\n          <tr><td>Géographie</td><td><span>Les</span> différentes espèces ont des répartitions et des formes cliniques variables (les arthrites de Lyme sont rares en Europe, fréquentes aux USA)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ <strong>Piège.</strong> L'<span class=\"nc-red nc-bold\">immunité spécifique </span><span><span class=\"nc-red nc-bold\">acquise</span></span><span class=\"nc-red nc-bold\"> </span><span><span class=\"nc-red nc-bold\">n'évite pas les réinfections</span></span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les phases évolutives de la maladie de Lyme","contenu":"<div class=\"notion-course\"><p>L'<span>évolution</span> de la maladie de Lyme se déroule classiquement en <strong>trois phases</strong>. La majorité des diagnostics est posée à la phase primaire ; mais l'<span><span class=\"nc-green nc-bold\">érythème migrant</span></span> étant <strong><span class=\"nc-red nc-bold\">inconstant</span></strong>, <span>les</span> phases disséminées peuvent révéler la maladie.</p>\n      <table>\n        <thead><tr><th>Phase</th><th>Délai</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Localisée précoce (primaire)</td><td><span>3-30 j</span> après la piqûre</td><td><span><span class=\"nc-green nc-bold\">Érythème migrant</span></span> <span class=\"nc-red nc-bold\">inconstant</span> ; multiplication de la bactérie dans le derme</td></tr>\n          <tr><td>Disséminée précoce</td><td><span><span class=\"nc-pink nc-bold\">&lt; 6 mois</span></span></td><td><span class=\"nc-red nc-bold\">Dissémination par voie hématogène</span> :<br><strong>Neurologique :</strong> <span><span class=\"nc-yellow_bg\">méningoradiculite</span></span> ; <span>méningite</span> ; (rarement) <span><span class=\"nc-orange_bg\">encéphalite</span></span> ou <span>myélite</span><br><strong>Articulaire :</strong> <span>oligoarthrite des grosses articulations</span> (<span class=\"nc-blue nc-bold\">genou</span>)<br><strong><span class=\"nc-brown nc-bold\">Cardiaque</span> :</strong> <span>myocardite</span> ; <span>troubles de conduction</span> (BAV) fluctuants<br><strong>Cutanée :</strong> <span>lymphocytome borrélien</span><br><strong>Ophtalmologique :</strong> <span>uvéites</span></td></tr>\n          <tr><td>Disséminée tardive (tertiaire)</td><td><span><span class=\"nc-pink nc-bold\">&gt; 6 mois</span></span></td><td>Mécanisme immunologique probable :<br><strong><span class=\"nc-brown nc-bold\">Cutanée</span> :</strong> <span>acrodermatite chronique atrophiante</span><br><strong>Neurologique :</strong> <span>polyneuropathie sensitive</span> ; <span>encéphalomyélite chronique</span><br><strong>Articulaire :</strong> <span><span class=\"nc-orange_bg\">mono ou oligo-arthrite chronique</span></span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/lyme-acrodermatite-atrophiante.png\" alt=\"Acrodermatite chronique atrophiante : placard cutané atrophique sur un membre, phase tertiaire de la maladie de Lyme\" loading=\"lazy\">\n        <figcaption>Acrodermatite chronique et atrophiante — manifestation cutanée quasi pathognomonique de la phase tertiaire de la borréliose de Lyme, évoquée surtout après <span>50 ans</span> : la <span>lésion</span> évolue d'une phase œdémateuse vers l'atrophie. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span>Paralysie faciale</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de Lyme","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-green nc-bold\">Érythème migrant</span> typique : diagnostic clinique, sans <span class=\"nc-red_bg nc-bold\">sérologie</span>, car celle-ci peut être <span class=\"nc-red nc-bold\">négative</span> précocement. Une fièvre ou des signes généraux n’excluent pas Lyme ; rechercher une autre infection transmise par <span class=\"nc-orange nc-bold\">tique</span> en cas de tableau atypique.</li><li>Formes disséminées : <span class=\"nc-blue_bg\">sérologie</span> en deux étapes, puis examens orientés par l’organe. <span class=\"nc-red nc-bold\">Neuroborréliose</span> : analyse du <span class=\"nc-red nc-bold\">LCS</span> et synthèse intrathécale selon délai et tableau ; arthrite : ponction pour exclure d’autres causes, avec <span class=\"nc-blue_bg\">PCR</span> ciblée si indiquée.</li><li>Une <span class=\"nc-red_bg nc-bold\">sérologie</span> positive témoigne d’un contact immunologique et ne prouve pas que des symptômes actuels sont dus à Lyme. Elle peut rester positive après guérison ; pas de contrôle sérologique pour juger l’efficacité.</li><li>Examiner peau, articulations, système nerveux et signes cardiaques. Palpitations, syncope ou trouble de conduction : ECG et évaluation urgente.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/lyme-em.jpg\" alt=\"Érythème migrant : macule érythémateuse annulaire à bordure active et centre plus clair\" loading=\"lazy\">\n        <figcaption><span>Érythème</span> migrant — lésion pathognomonique de la phase primaire de la maladie de Lyme : bordure annulaire centrifuge, centre éclairci, point d'inoculation parfois visible. Source : fiche source EDN item 173.</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-9","rang":"B","rubrique":"Prise en charge","titre":"Maladie de Lyme : connaître les principes de prise en charge phase primaire","contenu":"<div class=\"notion-course\"><ul><li>Lyme : antibiothérapie selon manifestation et âge. Recommandations 2025 : <span class=\"nc-green nc-bold\">érythème migrant</span> unique, <span class=\"nc-pink nc-bold\">doxycycline</span> dix jours ; érythèmes multiples, quatorze jours. <span class=\"nc-pink_bg\">Amoxicilline</span> quatorze jours en alternative et première intention chez l’enfant de moins de 20 kg.</li><li>L’interdiction générale de <span class=\"nc-pink nc-bold\">doxycycline</span> avant huit ans est dépassée pour certaines cures courtes ; grossesse et enfant requièrent le choix précis recommandé. Les formes neurologiques, articulaires et cardiaques ont leurs propres schémas.</li><li>Retrait mécanique rapide d’une tique, désinfection, surveillance de la zone et des symptômes. Pas de <span class=\"nc-red_bg nc-bold\">sérologie</span> ni d’antibioprophylaxie systématique après une simple piqûre en <span class=\"nc-green_bg\">France</span>.</li><li>Persistance de symptômes : réévaluer diagnostic et séquelles ; pas de répétition indéfinie d’antibiotiques sans <span class=\"nc-brown_bg\">infection active</span> documentée. Les autres zoonoses requièrent des traitements adaptés à leur agent.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Morsure</span> ou <span class=\"nc-blue_bg\">griffure</span> : lavage abondant, exploration et évaluation de la profondeur, des tendons/articulations, du terrain et du délai. Pasteurella peut provoquer rapidement une inflammation douloureuse ; une infection de <span class=\"nc-blue_bg\">morsure</span> peut être polymicrobienne.</li><li>Antibiothérapie ou prophylaxie si indiquée selon risque, usuellement amoxicilline–acide clavulanique pour couvrir la flore de <span class=\"nc-blue_bg\">morsure</span> ; documentation et adaptation dans les formes compliquées. L’amoxicilline seule peut convenir à une infection documentée sensible, pas à toute <span class=\"nc-blue_bg\">morsure</span>.</li><li>Vérifier vaccination antitétanique et risque rabique ; centre antirabique selon animal, lieu et circonstances. Main, articulation, immunodépression ou signes systémiques : avis rapide.</li><li>Drainage/débridement si nécessaire ; ne pas refermer automatiquement une plaie contaminée. Réévaluation précoce et information sur l’aggravation.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":4},{"id":"173-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la fièvre Q","contenu":"<div class=\"notion-course\"><p>La <span>fièvre Q</span> est une zoonose <span>bactérienne</span> due à <span>Coxiella burnetii</span>, bactérie <span>intracellulaire</span>.</p>\n      <table>\n        <tbody>\n          <tr><td>Réservoir</td><td>Placentas des animaux infectés — surtout <span>les</span> <span><span class=\"nc-green_bg\">ruminants</span></span> (<span><span class=\"nc-green_bg\">bovins</span></span>, <span><span class=\"nc-green_bg\">ovins</span></span>, <span><span class=\"nc-green_bg\">caprins</span></span>)</td></tr>\n          <tr><td>Transmission</td><td><strong>Inhalée :</strong> aérosols de <span class=\"nc-red nc-bold\">paille</span> et de <span class=\"nc-red nc-bold\">fumier</span> <span class=\"nc-red nc-bold\">contaminés</span> ; <br><strong>Digestive :</strong> consommation de <span class=\"nc-red nc-bold\">lait cru</span> ; <br><strong>Vecteur :</strong> <span class=\"nc-brown_bg\">tiques</span></td></tr>\n        </tbody>\n      </table>\n      <p>Infection <span><span class=\"nc-pink nc-bold\">asymptomatique</span> dans 60 %</span> des cas. Trois formes cliniques :</p>\n      <table>\n        <thead><tr><th>Forme</th><th>Caractéristiques</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Aiguë (la plus fréquente)</td><td><span class=\"nc-yellow_bg\">Incubation</span> ~<span><span class=\"nc-pink nc-bold\">3 semaines</span></span>, début pseudo-grippal, puis <span><span class=\"nc-blue_bg\">fièvre</span></span><span class=\"nc-blue_bg\"> isolée</span>, <strong><span><span class=\"nc-red nc-bold\">hépatite</span></span><span class=\"nc-red nc-bold\"> fébrile</span></strong> <span class=\"nc-red_bg\">(présentation la plus fréquente)</span> ou pneumopathie interstitielle</td><td><span><span class=\"nc-pink_bg\">Doxycycline</span></span> pendant <span><span class=\"nc-pink nc-bold\">2 à 3 semaines</span></span></td></tr>\n          <tr><td>Chronique</td><td><span>Terrain</span> : immunodéprimé, porteur de <span>lésion</span> valvulaire ou vasculaire → <span>endocardite à hémocultures négatives</span>, <span class=\"nc-red_bg\">infection vasculaire</span> (<span class=\"nc-pink nc-bold\">anévrisme</span>, prothèse)</td><td><span><span class=\"nc-pink_bg\">Doxycycline</span> + <span class=\"nc-pink_bg\">hydroxychloroquine</span></span>, durée prolongée (<span>18 à 24 mois</span>)</td></tr>\n          <tr><td>Femme enceinte</td><td>Conséquences fœtales (fausses couches)</td><td><span>Cotrimoxazole</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations biologiques</strong> : <span><span class=\"nc-blue_bg\">thrombopénie</span></span>, <span><span class=\"nc-blue_bg\">leuco-neutropénie</span></span> possible, <span><span class=\"nc-blue_bg\">cytolyse hépatique</span></span>, allongement du <span>TCA</span> (<span>anticoagulant</span> circulant).</p>\n      <p><strong>Microbiologie</strong> : <span><span class=\"nc-blue_bg\">sérologie</span></span> de <em>Coxiella burnetii</em> — le type d'anticorps identifié oriente vers une forme chronique ; <span><span class=\"nc-brown_bg\">PCR</span></span> et culture possibles en centre de référence.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span>Endocardite</span> infectieuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-12","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmission de la rage","contenu":"<div class=\"notion-course\"><p>La <span>rage</span> est une zoonose <span>virale</span>, constamment mortelle une fois déclarée.</p>\n      <table>\n        <tbody>\n          <tr><td>Agent</td><td><span><span class=\"nc-purple_bg\">Lyssavirus</span></span> (famille des <em>Rhabdoviridae</em>) — virus <span><span class=\"nc-red\">neurotrope</span></span>, fragile, rapidement détruit dans le <span class=\"nc-green_bg\">milieu extérieur</span></td></tr>\n          <tr><td>Réservoir</td><td><span><span class=\"nc-green_bg\">Canidés</span></span>, <span><span class=\"nc-green_bg\">renard</span></span>, <span>chauve-souris</span></td></tr>\n          <tr><td>Transmission</td><td><span><span class=\"nc-blue_bg\">Morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>, <span>léchage</span> sur peau lésée ou muqueuse, par un animal infecté</td></tr>\n          <tr><td>Incubation</td><td>Longue — de <span><span class=\"nc-pink nc-bold\">10 jours</span></span> à <span><span class=\"nc-pink nc-bold\">1 an</span></span> ; plus courte si la zone d'inoculation est richement innervée (<span class=\"nc-purple_bg\">mains</span>, <span class=\"nc-purple_bg\">face</span>) ou proche du SNC</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ <strong><span>Épidémiologie</span> <span class=\"nc-green_bg\">France</span>.</strong> La <span class=\"nc-green_bg\">France</span> est <strong>indemne de <span class=\"nc-green_bg\">rage</span></strong> chez <span>les</span> animaux terrestres non volants. Le risque résiduel est lié aux <span>chauves-souris</span>, à un <span>animal importé</span> d'une zone d'enzootie, ou à une <span><span class=\"nc-blue_bg\">morsure</span> à l'étranger</span> en zone d'enzootie. Environ 55 000 décès par an dans le monde.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les situations à risque et les principes de la prise en charge","contenu":"<div class=\"notion-course\"><ul><li>Après exposition rabique possible : lavage eau–savon pendant quinze minutes puis antisepsie. Évaluer l’animal, le pays, le type de contact et la vaccination antérieure ; consulter rapidement un centre antirabique.</li><li>La prophylaxie associe vaccin et, dans certaines expositions, immunoglobulines. Son schéma dépend du protocole et de l’immunisation antérieure ; la série « J0, J3, J7, J14, J15 » de l’ancienne fiche est erronée.</li><li>Une vaccination pré-exposition ne dispense pas de consultation ni de rappels après exposition. Ne pas attendre les symptômes, après lesquels la maladie est presque toujours mortelle.</li><li>Chauves-souris, exposition en zone d’endémie ou animal récemment importé : situations particulièrement importantes. La seule absence de certificat vaccinal d’un animal ne suffit pas à définir le risque ; l’évaluation est spécialisée.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":1},{"id":"173-14","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les circonstances imposant la recherche d’une toxoplasmose","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-orange_bg\">toxoplasmose</span></span> (parasite <span><span class=\"nc-purple_bg\">Toxoplasma gondii</span></span>, protozoaire intracellulaire) est une <span class=\"nc-red nc-bold\">zoonose </span><strong><span class=\"nc-red nc-bold\">cosmopolite</span></strong>, en règle <strong>bénigne</strong>. Sa recherche s'impose dans <span>les</span> <strong>situations où elle peut être grave</strong> :</p>\n      <ul>\n        <li><strong>Femme enceinte</strong> — risque de <span>toxoplasmose congénitale</span> : <span>sérologie</span> <span class=\"nc-red nc-bold\">obl</span><span><span class=\"nc-red nc-bold\">iga</span></span><span class=\"nc-red nc-bold\">toire</span> au 1ᵉʳ trimestre, puis <span>surveillance</span> mensuelle si la mère n'est pas immune.</li>\n        <li><strong>Patient immunodéprimé</strong> (<span>VIH</span> avec <span>CD4 &lt; 200/mm³</span>) — risque de <span>réactivation cérébrale</span> : tout tableau neurologique central doit faire évoquer le diagnostic.</li>\n        <li><strong>Bilan pré-transplantation</strong> — statut sérologique du donneur et du receveur d'organe.</li>\n      </ul>\n      <table>\n        <tbody>\n          <tr><td>Réservoirs</td><td><span><span class=\"nc-green_bg\">Chat</span></span> (hôte définitif), <span><span class=\"nc-green_bg\">ruminants</span></span> (bovins, <span class=\"nc-green_bg\">ovins</span>), <span><span class=\"nc-green_bg\">porcins</span></span></td></tr>\n          <tr><td>Transmission</td><td><strong><span>Oocystes</span> :</strong> <span class=\"nc-red nc-bold\">litière du chat</span>, crudités souillées par la terre ; <br><strong><span>Kystes</span> :</strong> <span class=\"nc-red nc-bold\">viande mal cuite</span>, <span class=\"nc-red nc-bold\">lait non pasteurisé</span> ; <br><strong>Materno-fœtale :</strong> passage transplacentaire ; <br><strong><span>Iatrogène</span> :</strong> transfusion sanguine, transplantation d'organe</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Prévention primaire</span></strong> : viande bien cuite (<span>72 °C</span>) ou congelée (<span>–18 °C</span>), <span class=\"nc-green_bg\">crudités et fruits lavés</span>, lavage des mains et des ustensiles, port de gants pour le changement de <span class=\"nc-red nc-bold\">litière du chat</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span>VIH</span> · 27 — Prévention risques fœtaux</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","contenu":"<div class=\"notion-course\"><p>Chez le sujet <strong>immunocompétent</strong>, la <span><span class=\"nc-yellow_bg\">primo-infection</span></span> toxoplasmique est le plus souvent bénigne.</p>\n      <table>\n        <tbody>\n          <tr><td>Incubation</td><td><span><span class=\"nc-pink_bg\">5 jours à 3 semaines</span></span> selon le mode de contamination</td></tr>\n          <tr><td>Forme habituelle</td><td><span><span class=\"nc-green nc-bold\">Asymptomatique</span></span> dans la majorité des cas</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations cliniques</strong> (<span>10-20 %</span> des cas) :</p>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Fièvre</span></span><span class=\"nc-blue_bg\"> modérée</span>, <span><span class=\"nc-blue_bg\">asthénie</span></span>, <span><span class=\"nc-blue_bg\">céphalées</span></span>, arthromyalgies.</li>\n        <li><span>Polyadénopathie</span> — notamment <strong>cervicale et occipitale</strong>, pouvant persister <span class=\"nc-pink nc-bold\">plusieurs semaines</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Angine érythémato-pultacée</span></span>, <span><span class=\"nc-blue_bg\">éruption</span></span><span class=\"nc-blue_bg\"> maculo-papuleuse</span>.</li>\n        <li><span>Choriorétinite</span> (uvéite postérieure) dans <span>5-10 %</span> des cas.</li>\n      </ul>\n      <p><strong>Manifestations biologiques</strong>, non spécifiques : <span><span class=\"nc-blue_bg\">syndrome mononucléosique</span></span> modéré, <span><span class=\"nc-blue_bg\">hyperéosinophilie</span></span> modérée, <span><span class=\"nc-blue_bg\">cytolyse hépatique</span></span>.</p>\n      <p><strong>Diagnostic</strong> : <span><span class=\"nc-blue nc-bold\">sérologie toxoplasmose</span></span> — <span>IgM</span> positives sans IgG en faveur d'une toxoplasmose en cours (<span>les</span> IgG montent ~<span>2 <span class=\"nc-pink nc-bold\">semaines</span></span> plus tard) ; étude comparative de 2 sérums à<span> <span class=\"nc-blue_bg nc-bold\">21 jours</span></span><span class=\"nc-blue_bg nc-bold\"> d'intervalle</span> si les <span>IgG</span> sont déjà présentes à taux élevé.</p>\n      <div class=\"callout callout-info\">À retenir : chez l'immunocompétent, l'<span>évolution</span> est bénigne et il n'y a <strong>pas d'indication de traitement</strong>.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Des IgM anti-toxoplasme isolées ne datent pas une infection : confirmation, évolution des IgG et avidité selon contexte. Chez l’immunocompétent, la forme habituelle guérit souvent sans traitement ; atteinte <span class=\"nc-brown nc-bold\">oculaire</span> ou forme sévère = avis spécialisé.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunodéprimé + femme enceinte","contenu":"<div class=\"notion-course\"><ul><li>Toxoplasmose chez l’immunodéprimé : réactivation fréquente, notamment cérébrale ; déficit focal, crises ou <span class=\"nc-blue_bg\">céphalées</span> imposent imagerie et diagnostic différentiel. Une <span class=\"nc-red_bg nc-bold\">sérologie</span> <span class=\"nc-red nc-bold\">négative</span> rend la réactivation moins probable sans exclure toute toxoplasmose.</li><li>VIH : cotrimoxazole en première intention des recommandations HAS 2024, traitement d’attaque six semaines puis entretien ; <span class=\"nc-pink_bg\">pyriméthamine</span>–<span class=\"nc-pink_bg\">sulfadiazine</span>–<span class=\"nc-green_bg\">acide</span> <span class=\"nc-green_bg nc-bold\">folinique</span> est une alternative. Surveiller réponse clinique/radiologique et toxicité.</li><li>Grossesse : dater et confirmer une infection maternelle par expertise sérologique ; organiser traitement et diagnostic prénatal avec une équipe spécialisée. Risque de transmission croissant avec le terme, gravité fœtale généralement plus importante si infection précoce.</li><li>PCR sur liquide amniotique selon terme et délai après infection ; un résultat négatif n’exclut pas toutes les infections tardives. Le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> exposé nécessite un bilan et un suivi spécifiques.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/toxo-cerebrale-cocarde-irm-1.png\" alt=\"IRM cérébrale T1 après gadolinium : abcès toxoplasmique en cocarde avec prise de contraste annulaire\" loading=\"lazy\">\n        <figcaption><span>IRM</span> cérébrale T1 après gadolinium — <span>abcès</span> toxoplasmique en cocarde : capsule rehaussée par le produit de contraste, centre nécrotique en hyposignal. Source : fiche source EDN item 173.</figcaption>\n      </figure><figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/toxo-cerebrale-cocarde-irm-2.png\" alt=\"IRM cérébrale T1 après gadolinium : seconde lésion toxoplasmique en cocarde\" loading=\"lazy\">\n        <figcaption><span>IRM</span> cérébrale T1 après gadolinium — autre coupe : <span>lésion</span> en cocarde caractéristique de la toxoplasmose cérébrale du sujet immunodéprimé. Source : fiche source EDN item 173.</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-17","rang":"B","rubrique":"Étiologies","titre":"Connaître les espèces à l’origine des deux formes d’échinococcose","contenu":"<div class=\"notion-course\"><p>L'<span>échinococcose</span> existe sous deux formes, dues à deux espèces distinctes du genre <span>Echinococcus</span> (<span>cestodes / ténias</span> — plathelminthes segmentés).</p>\n      <table>\n        <thead><tr><th></th><th><span class=\"nc-orange_bg\">Échinococcose hydatique</span></th><th><span class=\"nc-orange_bg\">Échinococcose alvéolaire</span></th></tr></thead>\n        <tbody>\n          <tr><td>Agent</td><td><span><span class=\"nc-purple nc-bold\">Echinococcus granulosus</span></span></td><td><span><span class=\"nc-purple nc-bold\">Echinococcus multilocularis</span></span></td></tr>\n          <tr><td>Hôte définitif</td><td><strong><span>Chien</span></strong></td><td><strong><span><span class=\"nc-red nc-bold\">Renard</span></span></strong>, <span>chien</span></td></tr>\n          <tr><td>Hôte intermédiaire</td><td><span><span class=\"nc-yellow_bg nc-bold\">Mouton</span></span></td><td><span>Rongeurs</span></td></tr>\n          <tr><td>Géographie</td><td>Parasitose <span><span class=\"nc-red nc-bold\">cosmopolite</span></span> : régions d'élevage (Maghreb, <span class=\"nc-green_bg\">sud de la France</span>)</td><td>Nord et centre de l'Europe (Vosges, Jura, Alpes, Massif central)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans <span>les</span> deux cas, l'<strong><span class=\"nc-yellow_bg\">homme est un </span><span><span class=\"nc-yellow_bg\">hôte accidentel</span></span></strong> (impasse <span>parasitaire</span>), contaminé par <span>contact</span> direct avec l'hôte définitif ou indirectement via des aliments, l'<span class=\"nc-red nc-bold\">eau</span> ou des objets souillés par les déjections.</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les localisations préférentielles des échinococcoses","contenu":"<div class=\"notion-course\"><p><span>Les</span> deux échinococcoses ont des <strong>localisations préférentielles</strong> distinctes.</p>\n      <p><strong><span class=\"nc-orange_bg\">Échinococcose hydatique</span> (kyste hydatique)</strong> — l'œuf embolise le système circulatoire au niveau du <span class=\"nc-purple_bg\">tube digestif</span>, puis se fixe :</p>\n      <table>\n        <thead><tr><th>Localisation</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span>Foie</span></td><td><span>50-60 %</span></td></tr>\n          <tr><td><span>Poumon</span></td><td><span>30-40 %</span></td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Autres organes</span></td><td><span>10 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le plus souvent <span><span class=\"nc-pink nc-bold\">asymptomatique</span></span> (découverte fortuite à l'imagerie) : <span>hépatomégalie</span> isolée <span><span class=\"nc-blue_bg\">indolore</span></span> pour la forme hépatique ; <span><span class=\"nc-blue_bg\">toux</span></span>, <span><span class=\"nc-blue_bg\">dyspnée</span></span>, <span><span class=\"nc-blue_bg\">hémoptysie</span></span> pour la forme pulmonaire. À l'<span>imagerie</span>, le kyste peut prendre l'aspect d'un kyste biliaire simple, d'une <span>paroi calcifiée</span> (kyste mort), ou d'une <span>membrane décollée ou flottante</span>.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong><span>Drapeau rouge</span>.</strong> La <span>ponction d'un kyste hydatique est formellement contre-indiquée</span> — <span class=\"nc-red nc-bold\">risque de </span><span><span class=\"nc-red nc-bold\">dissémination intrapéritonéale</span></span> et de réaction anaphylactique. Aucune image kystique intrahépatique ne se ponctionne sans <span><span class=\"nc-blue_bg\">sérologie</span></span> préalable.</div>\n      <p><strong><span class=\"nc-orange_bg\">Échinococcose alvéolaire</span></strong> — localisation <strong>intra-hépatique</strong> : <span>masse hépatique pseudo-tumorale infiltrante</span>, <span>mimant une néoplasie</span> à l'imagerie ; complications par <span>compression des voies biliaires</span> et des organes adjacents.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-1.png\" alt=\"Imagerie d&#x27;un kyste hydatique hépatique\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — aspect d'imagerie. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-2.png\" alt=\"Imagerie d&#x27;un kyste hydatique : décollement de membrane\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — décollement de membrane dans le liquide du kyste. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-3.png\" alt=\"Imagerie d&#x27;un kyste hydatique\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — aspect d'imagerie. Source : fiche source EDN item 173.</figcaption>\n      </figure><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La ponction diagnostique non préparée d’un kyste suspect d’hydatidose est à proscrire. Cela n’interdit pas la technique thérapeutique spécialisée PAIR dans certaines formes sélectionnées, avec précautions et couverture antiparasitaire. Une calcification ne prouve pas à elle seule que tout le kyste est inactif.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0},{"id":"173-19","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic de leishmaniose cutanée","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-orange_bg\">leishmaniose</span></span> est une parasitose due à un protozoaire du genre <span>Leishmania</span>.</p>\n      <table>\n        <tbody>\n          <tr><td>Vecteur</td><td>Insecte piqueur nocturne — le <span><span class=\"nc-yellow_bg nc-bold\">phlébotome</span></span></td></tr>\n          <tr><td>Réservoir</td><td><span>Chien</span>, <span><span class=\"nc-blue_bg\">rongeurs</span></span>, <span>homme</span></td></tr>\n          <tr><td>Géographie</td><td><span class=\"nc-green_bg\">Pourtour méditerranéen</span> (<span class=\"nc-green_bg\">France</span>) et zones tropicales (voyageurs)</td></tr>\n          <tr><td>Incubation</td><td><span><span class=\"nc-pink nc-bold\">Plusieurs semaines</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Leishmaniose cutanée</strong> — à évoquer devant une <span>lésion</span> sur une <strong>zone découverte</strong>, évoluant en trois temps :</p>\n      <ol>\n        <li>Une <span>papule carmin</span> infiltrée, initialement.</li>\n        <li>Puis une <span>ulcération secondaire avec croûte</span>, <span class=\"nc-blue_bg\">entourée d'un bourrelet rouge</span>, <strong><span><span class=\"nc-blue_bg\">indolore</span></span></strong>.</li>\n        <li><span><span class=\"nc-orange_bg\">Évolution</span></span><span class=\"nc-orange_bg\"> </span><span><span class=\"nc-orange_bg\">chronique</span></span> sur plusieurs mois.</li>\n      </ol>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/leishmaniose-papule-carmin.png\" alt=\"Leishmaniose cutanée : papule carmin infiltrée sur zone découverte\" loading=\"lazy\">\n        <figcaption>Leishmaniose cutanée — <span>papule</span> carmin infiltrée, lésion initiale. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/leishmaniose-ulceration-croute.png\" alt=\"Leishmaniose cutanée : ulcération secondaire recouverte d&#x27;une croûte\" loading=\"lazy\">\n        <figcaption>Leishmaniose cutanée — <span>ulcération</span> secondaire et croûte entourée d'un bourrelet rouge. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <p><strong>Diagnostic</strong> : <span>examen direct</span> sur frottis de grattage du pourtour de la <span>lésion</span> ou <span><span class=\"nc-blue_bg\">biopsie</span></span> ; <span><span class=\"nc-blue_bg\">PCR</span></span> sur la peau.</p>\n      <div class=\"callout callout-info\">Pour contraste : la <strong><span class=\"nc-orange_bg\">leishmaniose</span> viscérale</strong> (kala-azar), plus rare et touchant l'<span class=\"nc-red nc-bold\">enfant</span> ou l'<span class=\"nc-red nc-bold\">immunodéprimé</span>, associe <span><span class=\"nc-yellow_bg\">fièvre</span></span><span class=\"nc-yellow_bg\"> hectique</span>, <span><span class=\"nc-blue_bg\">splénomégalie</span></span> et <span>pancytopénie</span> ; son diagnostic repose sur le <span>myélogramme</span> et la <span><span class=\"nc-blue_bg\">sérologie</span></span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 173</a></li><li><a href=\"https://www.infectiologie.com/UserFiles/File/spilf/atb/info-antibio/info-antibio-2025-02-lyme.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SPILF · synthèse des recommandations Lyme 2025</a></li><li><a href=\"https://www.pasteur.fr/fr/votre-sante/comprendre-les-maladies/les-maladies-de-z/rage\" target=\"_blank\" rel=\"noopener noreferrer\">Institut Pasteur · rage, transmission et prophylaxie</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Rage :</strong> <span class=\"kw-alerte\">urgence</span> post-exposition — la maladie est <span class=\"kw-alerte\">constamment mortelle une fois les signes déclarés</span>, sans <span class=\"kw-alerte\">traitement curatif</span>. Désinfection immédiate de la plaie, puis stratification du risque rabique.</p><p><strong>Pasteurellose :</strong> incubation <span class=\"kw-chiffre\">extrêmement rapide (3 à 6 h)</span> après morsure ou griffure de chat — un <span class=\"kw-clinique\">placard</span> <span class=\"kw-etio\">inflammatoire</span> très précoce impose une consultation sans délai.</p><p><strong>Toxoplasmose cérébrale :</strong> chez l’immunodéprimé, tout tableau neurologique central impose une <span class=\"kw-imagerie\">IRM/TDM cérébrale</span> en <span class=\"kw-chiffre\">urgence</span>.</p><p><strong>Kyste hydatique :</strong> <span class=\"kw-ci\">aucune image kystique ne se ponctionne sans sérologie préalable</span> — risque de <span class=\"kw-alerte\">dissémination intrapéritonéale</span> et d’<span class=\"kw-alerte\">anaphylaxie</span>.</p>","hospit":"<p><strong>Rage, risque élevé :</strong> orientation obl<span class=\"kw-chiffre\">iga</span>toire vers un <span class=\"kw-def\">Centre Antirabique (CAR)</span> pour <span class=\"kw-ttt\">vaccination curative + Ig spécifiques</span> ; risque non exclu : <span class=\"kw-ttt\">vaccination curative</span> réalisable par tout médecin.</p><p><strong>Toxoplasmose &amp; <span class=\"kw-ci\">grossesse</span> :</strong> en cas de séroconversion, orientation vers un <span class=\"kw-def\">CPDPN</span> et <span class=\"kw-ttt\">spiramycine</span> sans attendre <span class=\"kw-clinique\">les</span> résultats du diagnostic anténatal.</p><p><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-imagerie\">imagerie</span> urgente et <span class=\"kw-ttt\">traitement d’épreuve</span> ; <span class=\"kw-bio\">biopsie stéréotaxique</span> si pas d’amélioration à <span class=\"kw-chiffre\">J15</span>.</p><p><strong>Échinococcoses :</strong> prise en charge chirurgicale en milieu spécialisé — <span class=\"kw-ci\">jamais de</span> <span class=\"kw-ttt\">ponction</span> à l’aveugle.</p><p><strong>Lyme :</strong> ambulatoire à la phase primaire ; les formes disséminées (neuroborréliose) relèvent d’une <span class=\"kw-ttt\">ceftriaxone</span> parentérale.</p>","redflags":"<ul><li><strong>Rage :</strong> <span class=\"kw-alerte\">spasme hydrophobique</span> et tableau d’<span class=\"kw-alerte\">encéphalite</span> = rage déclarée, <span class=\"kw-alerte\">constamment mortelle</span>.</li><li><strong>Pasteurellose :</strong> <span class=\"kw-alerte\">cellulite</span>, <span class=\"kw-alerte\">phlegmon des gaines</span>, <span class=\"kw-alerte\">arthrite</span>, <span class=\"kw-alerte\">bactériémie</span> chez l’immunodéprimé (cirrhotique).</li><li><strong>Toxoplasmose de l’immunodéprimé :</strong> <span class=\"kw-alerte\">déficit neurologique focal</span>, <span class=\"kw-alerte\">crises convulsives</span> avec <span class=\"kw-bio\">CD4 &lt; 200/mm³</span>.</li><li><strong>Toxoplasmose <span class=\"kw-etio\">congénitale</span> :</strong> <span class=\"kw-alerte\">primo-infection maternelle au 1ᵉʳ trimestre</span> — embryo-fœtopathies sévères, avortement.</li><li><strong>Kyste hydatique :</strong> <span class=\"kw-alerte\">rupture ou fissure</span> (<span class=\"kw-alerte\">anaphylaxie</span>) et <span class=\"kw-alerte\">compression des voies biliaires</span>.</li><li><strong><span class=\"kw-clinique\">Fièvre</span> Q chronique :</strong> <span class=\"kw-alerte\">endocardite à hémocultures négatives</span>, infection vasculaire (anévrisme, prothèse).</li></ul>","principes":"<p>Traitement orienté par la zoonose ; molécules, durées et gestes clés ci-dessous.</p><p><strong>Maladie des griffes du chat</strong></p><ul><li><span class=\"kw-ttt\">Azithromycine</span> pendant <span class=\"kw-chiffre\">5 jours</span> — <span class=\"kw-ttt\">antibiothérapie</span> discutée, l’<span class=\"kw-clinique\">évolution</span> étant spontanément favorable.</li></ul><p><strong>Pasteurellose</strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> pendant <span class=\"kw-chiffre\">7 jours</span> ; si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">céphalosporine</span> ou <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-clinique\">les</span> cyclines sont l’ATB de choix sur <em>Pasteurella multocida</em>).</li><li>Plaie : désinfection + <span class=\"kw-ttt\">antibioprophylaxie</span> par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>.</li></ul><p><strong>Maladie de Lyme</strong></p><ul><li>Phase primaire (<span class=\"kw-clinique\">érythème</span> migrant) — adulte : <span class=\"kw-ttt\">doxycycline</span> per os <span class=\"kw-chiffre\">14 jours</span> (10 j selon la HAS) ; enfant &lt;<span class=\"kw-chiffre\"> 8 ans</span> : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">14 jours</span> (<span class=\"kw-ci\">doxycycline contre-indiquée</span>).</li><li>Phases disséminées (neuroborréliose) : <span class=\"kw-ttt\">ceftriaxone</span> parentérale <span class=\"kw-chiffre\">2 g/j pendant 15-21 j</span> ou <span class=\"kw-ttt\">doxycycline</span> per os.</li><li>Après piqûre : retrait au <span class=\"kw-ttt\">tire-tique</span> + désinfection ; <span class=\"kw-ci\">pas d’antibioprophylaxie post-piqûre</span>.</li></ul><p><strong><span class=\"kw-clinique\">Fièvre</span> Q</strong></p><ul><li>Aiguë : <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">2 à 3 semaines</span>.</li><li>Chronique (<span class=\"kw-clinique\">endocardite</span>, infection vasculaire) : <span class=\"kw-ttt\">doxycycline + hydroxychloroquine</span>, <span class=\"kw-chiffre\">18 mois</span> (<span class=\"kw-chiffre\">24 mois</span> si matériel).</li><li>Femme enceinte : <span class=\"kw-ttt\">cotrimoxazole</span>.</li></ul><p><strong>Rage (post-exposition)</strong></p><ul><li>Risque non exclu : <span class=\"kw-ttt\">vaccination curative</span> seule, réalisable par tout médecin.</li><li>Risque élevé : en <span class=\"kw-def\">CAR</span> — <span class=\"kw-ttt\">vaccination curative + Ig spécifiques</span> ; protocole « Essen » <span class=\"kw-chiffre\">5 injections (J0, J3, J7, J14, J15)</span> ou « 2-1-1 de Zagreb ».</li><li>Aucun <span class=\"kw-alerte\">traitement curatif</span> une fois la rage déclarée.</li></ul><p><strong>Toxoplasmose</strong></p><ul><li>Immunocompétent : <span class=\"kw-ci\">pas de traitement</span> (<span class=\"kw-clinique\">évolution</span> bénigne).</li><li>Cérébrale (immunodéprimé) : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span>, <span class=\"kw-chiffre\">3 à 6 semaines</span> (<span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span> aux <span class=\"kw-ttt\">sulfamides</span>).</li><li><span class=\"kw-ci\">Grossesse</span> — séroconversion : <span class=\"kw-ttt\">spiramycine</span> ; atteinte fœtale confirmée : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span>.</li></ul><p><strong>Échinococcose hydatique</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> ++ : <span class=\"kw-ttt\">exérèse complète sans ouverture du kyste</span> ; <span class=\"kw-ttt\">PAIR</span> (<span class=\"kw-ttt\">ponction</span>-aspiration-injection-réaspiration) si exérèse impossible.</li><li><span class=\"kw-ttt\">Albendazole</span><span class=\"kw-chiffre\"> 1 mois</span> avant et <span class=\"kw-chiffre\">1 mois</span> après le geste, ou prolongé si <span class=\"kw-ttt\">chirurgie</span> impossible.</li></ul><p><strong>Leishmaniose</strong></p><ul><li>Cutanée : traitement local — <span class=\"kw-ttt\">antimonié</span>, <span class=\"kw-ttt\">cryothérapie</span>, <span class=\"kw-ttt\">paromomycine</span> crème.</li><li>Viscérale (kala-azar) : <span class=\"kw-ttt\">amphotéricine B liposomale</span> par voie systémique.</li></ul>","suivi":"<p><strong>Rage (risque quasi nul) :</strong> <span class=\"kw-clinique\">surveillance vétérinaire</span> de l’animal vivant (chien, chat, furet) — 3 certificats à <span class=\"kw-chiffre\">J0, J7, J15</span> ; si mort ou euthanasie : analyse de la tête (<span class=\"kw-bio\">PCR</span>, <span class=\"kw-bio\">immunofluorescence</span>, <span class=\"kw-bio\">culture</span>).</p><p><strong>Toxoplasmose &amp; <span class=\"kw-ci\">grossesse</span> :</strong> femme non immune → <span class=\"kw-bio\">sérologie mensuelle</span> jusqu’à l’accouchement, avec <span class=\"kw-def\">suivi</span> <span class=\"kw-imagerie\">échographique</span> mensuel.</p><p><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-def\">réévaluation</span> clinico-radiologique à <span class=\"kw-chiffre\">J15</span> du <span class=\"kw-ttt\">traitement d’épreuve</span> ; <span class=\"kw-bio\">biopsie stéréotaxique</span> si échec (évoquer un <span class=\"kw-def\">lymphome cérébral</span>).</p><p><strong>Échinococcose sous albendazole :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">hépatique</span> et des <span class=\"kw-bio\">leucocytes</span>.</p><p><strong>Lyme :</strong> pas de <span class=\"kw-bio\">sérologie</span> de contrôle systématique ; <span class=\"kw-ci\">pas de dépistage du sujet exposé asymptomatique</span>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf","label":"Collège Pilly — Zoonoses (item 173, PDF)"},{"href":"https://radiopaedia.org/articles/neurotoxoplasmosis","label":"Radiopaedia : Neurotoxoplasmosis"},{"href":"https://radiopaedia.org/articles/lyme-disease","label":"Radiopaedia : Lyme disease"},{"href":"https://radiopaedia.org/articles/hydatid-disease","label":"Radiopaedia : Hydatid disease"},{"href":"https://radiopaedia.org/articles/alveolar-echinococcosis","label":"Radiopaedia : Alveolar echinococcosis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Exposition à un animal : morsure, griffure ou léchage — Désinfection immédiate de la plaie, puis évaluation du risque rabique","detail":"<h4>CAT — Exposition à un animal mordeur ou griffeur — Stratifier le risque rabique après morsure, griffure ou léchage sur peau lésée ou muqueuse</h4>","branches":[{"to":"t-declaree","label":"Signes neurologiques de rage déjà présents (encéphalite, hydrophobie)","color":"red"},{"to":"q-risque","label":"Exposition récente, pas de signe de rage","color":"blue"}]},{"id":"t-declaree","kind":"terminal","label":"Rage déclarée — soins de support","color":"red","detail":"<h4>Clinique</h4><ul><li>Tableau d’<span class=\"kw-def\">encéphalite</span> ; <span class=\"kw-clinique\">spasme hydrophobique</span> pathognomonique (contraction du pharynx empêchant la prise de boissons).</li></ul><h4>Conduite</h4><ul><li>Maladie <span class=\"kw-alerte\">constamment mortelle</span> une fois <span class=\"kw-clinique\">les</span> signes déclarés ; <span class=\"kw-alerte\">aucun traitement curatif</span>. Soins de support et palliatifs.</li></ul>"},{"id":"q-risque","kind":"decision","label":"Niveau de risque rabique selon le contexte — France indemne chez les animaux terrestres non volants ; risque lié aux chauves-souris, animaux importés ou morsures en zone d’enzootie","branches":[{"to":"t-surveillance","label":"Risque quasi nul : animal en France, propriétaire, à disposition, sans comportement suspect","color":"green"},{"to":"t-vaccination","label":"Risque non exclu : animal en France non importé, mais non à disposition (fugue, disparition)","color":"amber"},{"to":"q-immun","label":"Risque élevé : chauve-souris, zone d’enzootie, animal importé ou rage confirmée","color":"red"}]},{"id":"t-surveillance","kind":"terminal","label":"Surveillance vétérinaire de l’animal","color":"green","detail":"<h4>Conduite</h4><ul><li>Aucune mesure spécifique tant que l’animal ne développe pas de signe suspect de rage.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Surveillance vétérinaire</span> de l’animal vivant (chien, chat, furet) : 3 certificats à <span class=\"kw-chiffre\">J0</span>, <span class=\"kw-chiffre\">J7</span>, <span class=\"kw-chiffre\">J15</span>.</li></ul><h4>Si mort ou euthanasie</h4><ul><li>Analyse de la tête de l’animal pour diagnostic de certitude : <span class=\"kw-bio\">PCR</span>, <span class=\"kw-bio\">immunofluorescence</span>, <span class=\"kw-bio\">culture</span>.</li></ul>"},{"id":"t-vaccination","kind":"terminal","label":"Vaccination curative (tout médecin)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination curative antirabique</span> — réalisable par tout médecin, sans recours obl<span class=\"kw-chiffre\">iga</span>toire au CAR.</li></ul><h4>Protocole</h4><ul><li>« Essen » en <span class=\"kw-chiffre\">5 injections (J0, J3, J7, J14, J15)</span> ou « 2-1-1 de Zagreb » (2 injections à <span class=\"kw-chiffre\">J0</span> en sites différents, puis <span class=\"kw-chiffre\">J7</span> et <span class=\"kw-chiffre\">J21</span>).</li></ul>"},{"id":"q-immun","kind":"decision","label":"Patient déjà vacciné en pré-exposition ? — Le statut vaccinal antérieur conditionne l’administration des immunoglobulines","branches":[{"to":"t-car-vacc","label":"Oui — sujet complètement immunisé","color":"red"},{"to":"t-car-ig","label":"Non — sujet non immunisé","color":"red"}]},{"id":"t-car-vacc","kind":"terminal","label":"CAR — vaccination simplifiée, sans Ig","color":"red","detail":"<h4>Orientation</h4><ul><li>Adresser au <span class=\"kw-def\">Centre Antirabique (CAR)</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination</span> post-exposition simplifiée : <span class=\"kw-chiffre\">2 injections de rappel (J0, J3)</span>. Pas de <span class=\"kw-ttt\">sérothérapie</span> — inutile si le sujet est complètement immunisé.</li></ul>"},{"id":"t-car-ig","kind":"terminal","label":"CAR — vaccination curative + Ig spécifiques","color":"red","detail":"<h4>Orientation</h4><ul><li>Prise en charge <strong>uniquement en <span class=\"kw-def\">Centre Antirabique (CAR)</span></strong>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination curative</span> complète + <span class=\"kw-ttt\">sérothérapie par Ig spécifiques</span> antirabiques, débutées à <span class=\"kw-chiffre\">J0</span>.</li></ul><h4>Modalités Ig</h4><ul><li><span class=\"kw-ttt\">Ig spécifiques</span> injectées au site de la blessure (dedans et autour) et en IM à un site distant du vaccin.</li></ul><h4>Délai</h4><ul><li>Incubation longue (<span class=\"kw-chiffre\">10 jours</span> à <span class=\"kw-chiffre\">1 an</span>), plus courte si zone richement innervée (mains, face) — d’où l’<span class=\"kw-alerte\">urgence</span> de la <span class=\"kw-ttt\">prophylaxie post-exposition</span>.</li></ul>"}]},"cards":[{"i":"1fab8c18667b","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quels sont les principaux modes de transmission des zoonoses de l'animal à l'homme ?","a":"<div class=\"notion-course\"><ul><li><strong>Transmission directe</strong> par un animal (<span class=\"nc-blue_bg\">morsure</span>, <span class=\"nc-blue_bg\">griffure</span>, léchage, contact, <span class=\"nc-brown_bg\">voie digestive</span> ou inhalée).</li><li><strong>Transmission par un vecteur</strong>, comme un arthropode (tique, <span class=\"nc-yellow_bg nc-bold\">phlébotome</span>).</li><li><strong>Pathologie d'inoculation</strong>, par pénétration de l'agent à travers la peau ou les muqueuses.</li></ul></div>"},{"i":"31450eb68c91","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quelles sont les trois familles étiologiques principales des agents pathogènes responsables de zoonoses ?","a":"<div class=\"notion-course\"><ul><li><strong>Bactérienne</strong></li><li><strong>Virale</strong></li><li><strong>Parasitaire</strong></li></ul></div>"},{"i":"3830656f0800","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quelle est la définition d'une zoonose, en médecine infectieuse ?","a":"<div class=\"notion-course\"><p>Une zoonose est une <strong>maladie infectieuse</strong> transmise par un <strong>agent pathogène</strong> de l'<strong>animal à l'homme</strong>.</p></div>"},{"i":"73a0487b8b4d","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Comment définir cliniquement la pasteurellose et quel est son agent causal principal ?","a":"<div class=\"notion-course\"><p>La pasteurellose est une <strong>zoonose bactérienne d'inoculation</strong>, survenant classiquement après une <strong><span class=\"nc-blue_bg\">morsure</span> ou une <span class=\"nc-blue_bg\">griffure</span> de chat</strong>. L'agent causal est <em><strong><span class=\"nc-purple nc-bold\">Pasteurella multocida</span></strong></em>, un bacille à Gram négatif.</p></div>"},{"i":"7debc391346c","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quelle est la particularité du délai d'incubation de la pasteurellose et quels sont les signes cliniques locaux initiaux ?","a":"<div class=\"notion-course\"><ul><li>Inflammation rapidement douloureuse après <span class=\"nc-blue_bg\">morsure</span> ou <span class=\"nc-blue_bg\">griffure</span>, souvent en quelques heures : rougeur, œdème, parfois écoulement, <span class=\"nc-orange_bg\">lymphangite</span> et <span class=\"nc-yellow_bg nc-bold\">adénopathie</span>. Le délai court oriente mais n’est pas un critère obligatoire de trois à six heures.</li></ul></div>"},{"i":"a9f49db09dbe","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Comment établir le diagnostic microbiologique de la pasteurellose ?","a":"<div class=\"notion-course\"><ul><li>Culture d’un prélèvement pertinent de la lésion infectée ou profond si disponible ; <span class=\"nc-purple_bg\">hémocultures</span> si signes systémiques ou suspicion de bactériémie. Toute <span class=\"nc-blue_bg\">morsure</span> ne justifie pas automatiquement ces deux prélèvements.</li></ul></div>"},{"i":"c48cb9470c32","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quelles sont les complications possibles de la pasteurellose non ou mal traitée ?","a":"<div class=\"notion-course\"><p>Les complications possibles de la pasteurellose sont une <strong><span class=\"nc-red_bg\">cellulite</span></strong>, un <strong><span class=\"nc-red_bg\">phlegmon des gaines</span></strong> ou une <strong><span class=\"nc-red_bg\">arthrite</span></strong>. Chez les patients immunodéprimés (notamment les <strong>cirrhotiques</strong>), une <strong><span class=\"nc-red_bg\">bactériémie</span></strong> est à craindre.</p></div>"},{"i":"c949d772ea4c","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quels animaux constituent le réservoir principal de Pasteurella multocida et quels sont les modes de transmission de la pasteurellose ?","a":"<div class=\"notion-course\"><p>Le réservoir principal de <em><span class=\"nc-purple nc-bold\">Pasteurella multocida</span></em> est le <strong>chat</strong> (le plus fréquemment), mais aussi le <span class=\"nc-green_bg\">chien</span> et les <span class=\"nc-green_bg\">oiseaux</span>. La transmission se fait par <strong><span class=\"nc-blue_bg\">morsure</span>, <span class=\"nc-blue_bg\">griffure</span> ou piqûre végétale contaminée</strong>.</p></div>"},{"i":"237ce4bbfadf","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quel est l'agent causal de la rage et ses caractéristiques principales ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-green_bg\">rage</span> est causée par un <strong><span class=\"nc-purple_bg\">Lyssavirus</span></strong>, de la famille des <strong>Rhabdoviridae</strong>. C'est un virus <strong><span class=\"nc-red\">neurotrope</span></strong>, <strong>fragile</strong> et rapidement détruit dans le <span class=\"nc-green_bg\">milieu extérieur</span>.</p></div>"},{"i":"5fbee8a7bbbf","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les risques épidémiologiques résiduels de rage en France ?","a":"<div class=\"notion-course\"><p>Bien que la France soit indemne de rage chez les animaux terrestres non volants, le risque résiduel est lié :</p><ul><li>Aux <strong>chauves-souris</strong>.</li><li>À un <strong>animal importé</strong> d'une zone d'enzootie.</li><li>À une <strong>morsure contractée à l'étranger</strong> dans une zone d'enzootie.</li></ul></div>"},{"i":"644a70a40d1e","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les modes de transmission du virus de la rage à l'Homme ?","a":"<div class=\"notion-course\"><ul><li><strong>Morsure</strong> d'un animal infecté.</li><li><strong>Griffure</strong> d'un animal infecté.</li><li><strong>Léchage sur une peau lésée ou une muqueuse</strong> par un animal infecté.</li></ul></div>"},{"i":"c6870176b292","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les principaux réservoirs du virus de la rage ?","a":"<div class=\"notion-course\"><p>Les principaux réservoirs du virus de la <span class=\"nc-green_bg\">rage</span> sont les <strong><span class=\"nc-green_bg\">canidés</span></strong> (chiens, loups, etc.), le <strong><span class=\"nc-green_bg\">renard</span></strong>, et la <strong><span class=\"nc-green_bg\">chauve-souris</span></strong>.</p></div>"},{"i":"ea4a95a5afc3","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quelle est la durée d'incubation de la rage et quels facteurs peuvent la faire varier ?","a":"<div class=\"notion-course\"><p>L'incubation de la rage est généralement <strong>longue</strong>, variant de <strong><span class=\"nc-pink nc-bold\">10 jours</span> à <span class=\"nc-pink nc-bold\">1 an</span></strong>. Elle est plus courte si la zone d'inoculation est <strong>richement innervée</strong> (<span class=\"nc-purple_bg\">mains</span>, <span class=\"nc-purple_bg\">face</span>) ou proche du <strong>système nerveux central (<span class=\"nc-pink nc-bold\">SNC</span>)</strong>.</p></div>"},{"i":"4f81a6331561","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"Pour quelle patiente spécifique la recherche d'une toxoplasmose est-elle systématiquement imposée, et pourquoi ?","a":"<div class=\"notion-course\"><p>La recherche d'une toxoplasmose est systématiquement imposée chez la <strong>femme enceinte</strong> en raison du risque de <strong>toxoplasmose congénitale</strong>. Une sérologie est <span class=\"nc-red nc-bold\">obligatoire</span> au <span class=\"nc-pink nc-bold\">1er trimestre</span>, avec une surveillance mensuelle si la mère n'est pas immune.</p></div>"},{"i":"5e51b2d61845","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"En dehors des patients immunodéprimés et des femmes enceintes, dans quelle autre situation clinique la recherche de toxoplasmose est-elle nécessaire ?","a":"<div class=\"notion-course\"><p>La recherche de la toxoplasmose est nécessaire dans le cadre d'un <strong>bilan pré-transplantation</strong>, afin de déterminer le <strong>statut sérologique du donneur et du receveur d'organe</strong>.</p></div>"},{"i":"f927741037ca","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"Dans quels cas chez un patient immunodéprimé la recherche d'une toxoplasmose doit-elle être systématique ?","a":"<div class=\"notion-course\"><p>Chez un patient <strong>immunodéprimé</strong>, notamment un patient atteint du <strong>VIH avec CD4 &lt; 200/mm³</strong>, la recherche d'une toxoplasmose doit être systématique devant tout <strong>tableau neurologique central</strong>, en raison du risque de <strong>réactivation cérébrale</strong> de la toxoplasmose.</p></div>"},{"i":"4a3f7b3fba1c","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quelles sont les anomalies biologiques non spécifiques parfois associées à la primo-infection toxoplasmique chez l’immunocompétent ?","a":"<div class=\"notion-course\"><p>Les manifestations biologiques, non spécifiques, peuvent inclure :</p><ul><li>Un <strong><span class=\"nc-blue_bg\">syndrome mononucléosique</span></strong> modéré.</li><li>Une <strong><span class=\"nc-blue_bg\">hyperéosinophilie</span></strong> modérée.</li><li>Une <strong><span class=\"nc-blue_bg\">cytolyse hépatique</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Des IgM anti-toxoplasme isolées ne datent pas une infection : confirmation, évolution des IgG et avidité selon contexte. Chez l’immunocompétent, la forme habituelle guérit souvent sans traitement ; atteinte <span class=\"nc-brown nc-bold\">oculaire</span> ou forme sévère = avis spécialisé.</li></ul></div></div>"},{"i":"7f99bbb0cf6e","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quelles sont les caractéristiques cliniques de la primo-infection toxoplasmique chez le sujet immunocompétent ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-yellow_bg\">primo-infection</span> toxoplasmique est le plus souvent <strong>asymptomatique</strong> (majorité des cas). Lorsqu'elle est symptomatique (10-20% des cas), les manifestations comprennent :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">fièvre modérée</span></strong>, <span class=\"nc-blue_bg\">asthénie</span>, <span class=\"nc-blue_bg\">céphalées</span>, arthromyalgies.</li><li>Une <strong>polyadénopathie</strong>, notamment <strong>cervicale et occipitale</strong>, pouvant persister <span class=\"nc-pink nc-bold\">plusieurs semaines</span>.</li><li>Plus rarement, une <span class=\"nc-blue_bg\">angine érythémato-pultacée</span>, ou une <span class=\"nc-blue_bg\">éruption maculo-papuleuse</span>.</li><li>Une <strong>choriorétinite</strong> (uvéite postérieure) dans 5-10% des cas.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Des IgM anti-toxoplasme isolées ne datent pas une infection : confirmation, évolution des IgG et avidité selon contexte. Chez l’immunocompétent, la forme habituelle guérit souvent sans traitement ; atteinte <span class=\"nc-brown nc-bold\">oculaire</span> ou forme sévère = avis spécialisé.</li></ul></div></div>"},{"i":"bea8e983c0d4","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Comment interpréter la sérologie pour le diagnostic d'une toxoplasmose en cours chez un patient immuncompétent ?","a":"<div class=\"notion-course\"><p>Le diagnostic repose sur la <span class=\"nc-blue nc-bold\">sérologie toxoplasmose</span>. Une toxoplasmose en cours est suggérée par des <strong>IgM positives sans IgG détectables</strong> au début, les IgG montant ~ 2 <span class=\"nc-pink nc-bold\">semaines</span> plus tard.</p><p>En cas d'IgG déjà présentes à taux élevé, une <strong>étude comparative de 2 sérums avec <span class=\"nc-blue_bg nc-bold\">21 jours d'intervalle</span></strong> est nécessaire pour objectiver une séroconversion ou une ascension significative des titres.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Des IgM anti-toxoplasme isolées ne datent pas une infection : confirmation, évolution des IgG et avidité selon contexte. Chez l’immunocompétent, la forme habituelle guérit souvent sans traitement ; atteinte <span class=\"nc-brown nc-bold\">oculaire</span> ou forme sévère = avis spécialisé.</li></ul></div></div>"},{"i":"d8eb9bedfd9e","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quel est le pronostic et la prise en charge thérapeutique de la toxoplasmose chez le sujet immunocompétent ?","a":"<div class=\"notion-course\"><p>Chez le sujet immunocompétent, l'évolution de la toxoplasmose est <strong>bénigne</strong> et <strong>il n'y a pas d'indication de traitement</strong> spécifique.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Des IgM anti-toxoplasme isolées ne datent pas une infection : confirmation, évolution des IgG et avidité selon contexte. Chez l’immunocompétent, la forme habituelle guérit souvent sans traitement ; atteinte <span class=\"nc-brown nc-bold\">oculaire</span> ou forme sévère = avis spécialisé.</li></ul></div></div>"},{"i":"2138333077c9","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quel est le réservoir principal et les terrains les plus souvent touchés par la maladie des griffes du chat ?","a":"<div class=\"notion-course\"><p>Le réservoir principal est le <strong>chat</strong>, particulièrement le <strong>chaton</strong> et le <strong>jeune chat</strong>. Elle touche surtout l'<strong><span class=\"nc-pink nc-bold\">enfant</span></strong> et le <strong>jeune adulte</strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Bartonella est une bactérie difficile à cultiver ; la faible sensibilité des techniques usuelles oriente vers <span class=\"nc-yellow_bg nc-bold\">sérologie</span>/PCR selon contexte. La visibilité au Gram n’est pas le critère qui décide à elle seule si une culture est réalisable.</li></ul></div></div>"},{"i":"9d2b86942402","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Décrivez la physiopathologie de la maladie des griffes du chat en précisant les étapes clé de la transmission à l'homme et l'évolution locale.","a":"<div class=\"notion-course\"><p>La physiopathologie se déroule en quatre temps :</p><ul><li>Bactériémie asymptomatique chez le chat, qui contamine ses griffes.</li><li>Transmission à l'homme par <strong><span class=\"nc-blue_bg\">morsure</span></strong>, <strong><span class=\"nc-blue_bg\">griffure</span></strong>, plus rarement <span class=\"nc-blue_bg\">léchage de plaie</span> ou <span class=\"nc-blue_bg\">piqûre de puces de chat</span>.</li><li>Multiplication de la bactérie dans le <strong>ganglion relais</strong> du territoire de drainage lymphatique.</li><li>Développement d'une <strong><span class=\"nc-yellow_bg nc-bold\">adénopathie</span> inflammatoire</strong> caractérisée histologiquement par un <strong><span class=\"nc-pink nc-bold\">granulome épithélioïde sans nécrose caséeuse</span></strong>, une <span class=\"nc-pink nc-bold\">hyperplasie folliculaire</span> et des <span class=\"nc-pink nc-bold\">micro-abcès</span>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Bartonella est une bactérie difficile à cultiver ; la faible sensibilité des techniques usuelles oriente vers <span class=\"nc-yellow_bg nc-bold\">sérologie</span>/PCR selon contexte. La visibilité au Gram n’est pas le critère qui décide à elle seule si une culture est réalisable.</li></ul></div></div>"},{"i":"af8898a52264","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quel agent bactérien est responsable de la maladie des griffes du chat et quelques-unes de ses caractéristiques ?","a":"<div class=\"notion-course\"><p>L'agent responsable est <em><strong><span class=\"nc-purple_bg\">Bartonella henselae</span></strong></em>. C'est une <strong>bactérie intracellulaire</strong>, <strong>non visible à la coloration de Gram</strong>, rendant les hémocultures inefficaces pour son identification.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Bartonella est une bactérie difficile à cultiver ; la faible sensibilité des techniques usuelles oriente vers <span class=\"nc-yellow_bg nc-bold\">sérologie</span>/PCR selon contexte. La visibilité au Gram n’est pas le critère qui décide à elle seule si une culture est réalisable.</li></ul></div></div>"},{"i":"d72b1723f7c0","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quelle est la définition de la maladie des griffes du chat et son synonyme ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, ou <strong><span class=\"nc-yellow_bg\">lymphoréticulose bénigne d'inoculation</span></strong>, est une <strong>zoonose bactérienne bénigne d'inoculation</strong>.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Bartonella est une bactérie difficile à cultiver ; la faible sensibilité des techniques usuelles oriente vers <span class=\"nc-yellow_bg nc-bold\">sérologie</span>/PCR selon contexte. La visibilité au Gram n’est pas le critère qui décide à elle seule si une culture est réalisable.</li></ul></div></div>"},{"i":"289654aecb8d","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quelle est l'approche diagnostique initiale pour confirmer une maladie des griffes du chat ?","a":"<div class=\"notion-course\"><p>La confirmation d'une <span class=\"nc-purple_bg\">maladie des griffes du chat</span> repose en première intention sur la <strong><span class=\"nc-yellow_bg nc-bold\">sérologie</span></strong>. Cependant, sa sensibilité est faible, et une <span class=\"nc-yellow_bg nc-bold\">sérologie</span> <span class=\"nc-red nc-bold\">négative</span> n'élimine pas le diagnostic.</p></div>"},{"i":"6d86f2395f84","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quelles sont les caractéristiques cliniques de l'adénopathie associée à la maladie des griffes du chat ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-yellow_bg nc-bold\">adénopathie</span> de la <span class=\"nc-purple_bg\">maladie des griffes du chat</span> est généralement localisée au niveau du <strong>ganglion relais</strong>. Elle est :</p><ul><li><strong><span class=\"nc-pink nc-bold\">Unique</span></strong> dans 50 % des cas ou <span class=\"nc-pink nc-bold\">multiple</span> sur un seul territoire <strong>unilatéral</strong> (cervical, axillaire, épitrochléen, inguinal).</li><li>Souvent <strong><span class=\"nc-pink nc-bold\">volumineuse</span></strong>, <span class=\"nc-blue_bg\">ferme</span>, <span class=\"nc-blue_bg\">mobile</span>, <strong>inflammatoire</strong> et sensible.</li><li><span class=\"nc-pink nc-bold\">Parfois en voie de</span> <strong><span class=\"nc-pink nc-bold\">fistulisation</span></strong>.</li></ul></div>"},{"i":"88aa1c319c98","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"En cas de doute diagnostique pour la maladie des griffes du chat, quels sont les examens complémentaires à privilégier pour une confirmation ?","a":"<div class=\"notion-course\"><p>En cas de doute pour la <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, il faut privilégier :</p><ul><li>La <strong><span class=\"nc-blue_bg\">PCR spécifique</span></strong> sur exérèse ou biopsie ganglionnaire pour un <strong>diagnostic de certitude</strong>.</li><li>L'<strong><span class=\"nc-blue_bg\">histologie</span></strong> montrant un <strong><span class=\"nc-pink nc-bold\">granulome épithélioïde sans nécrose caséeuse</span></strong>, ce qui confère une forte présomption diagnostique.</li></ul></div>"},{"i":"8929203876e6","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quels sont les signes cliniques généraux et les formes atypiques de la maladie des griffes du chat ?","a":"<div class=\"notion-course\"><p>Les signes généraux de la <span class=\"nc-purple_bg\">maladie des griffes du chat</span> sont discrets et présents dans <strong>50 %</strong> des cas :</p><ul><li>Céphalées.</li><li>Asthénie.</li><li>Fébricule.</li><li><span class=\"nc-blue_bg\">Douleurs abdominales</span>.</li></ul><p>Deux formes cliniques particulières sont à connaître :</p><ul><li>Le <strong><span class=\"nc-orange_bg\">syndrome oculo-glandulaire de</span> <span class=\"nc-orange_bg nc-bold\">Parinaud</span></strong> (forme ophtalmique, 10 % des cas) avec <span class=\"nc-blue_bg\">conjonctivite</span> et adénopathie prétragienne.</li><li>Les <strong><span class=\"nc-orange_bg\">endocardites à hémocultures négatives</span></strong> (rares).</li></ul></div>"},{"i":"fc9cf4868192","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Comment se présente la lésion primaire d'inoculation dans la maladie des griffes du chat et où se localise-t-elle généralement ?","a":"<div class=\"notion-course\"><p>La lésion primaire d'inoculation de la <span class=\"nc-purple_bg\">maladie des griffes du chat</span> est présente dans <strong>50 %</strong> des cas. Il s'agit d'une <strong>trace de <span class=\"nc-blue_bg\">morsure</span> ou de <span class=\"nc-blue_bg\">griffure</span></strong> qui précède souvent une <span class=\"nc-yellow_bg nc-bold\">lésion érythémateuse papuleuse</span>.</p></div>"},{"i":"20002e3a4aed","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Comment la transmission de la bactérie de la maladie de Lyme s'opère-t-elle lors d'une piqûre de tique ?","a":"<div class=\"notion-course\"><p>La bactérie est inoculée par <strong>régurgitation</strong> au cours d'un repas sanguin de la tique.</p></div>"},{"i":"231286b1fd07","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Quels sont les facteurs d'exposition favorisant la transmission de la maladie de Lyme en France métropolitaine ?","a":"<div class=\"notion-course\"><p>Les principaux terrains d'exposition sont :</p><ul><li>Les <strong>promenades en forêt</strong>.</li><li>Les <strong>travaux agricoles et forestiers</strong>.</li></ul></div>"},{"i":"cdde6339d82a","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Quel est le vecteur de la bactérie responsable de la maladie de Lyme ?","a":"<div class=\"notion-course\"><p>La bactérie responsable de la maladie de Lyme, <em>Borrelia spp.</em>, est transmise par la piqûre de <strong><span class=\"nc-orange nc-bold\">tiques</span> du genre Ixodes</strong>.</p></div>"},{"i":"18cef274279c","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Quelle est la manifestation clinique pathognomonique de la maladie de Lyme et quelles en sont les caractéristiques ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-green nc-bold\">Érythème migrant</span> typique : plaque érythémateuse s’étendant progressivement, souvent peu douloureuse et peu prurigineuse. L’éclaircissement central n’est pas <span class=\"nc-red nc-bold\">obligatoire</span>. Le diagnostic est clinique et ne nécessite pas de <span class=\"nc-red_bg nc-bold\">sérologie</span>.</li></ul></div>"},{"i":"53dd626752e3","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Comment réaliser le diagnostic biologique de la maladie de Lyme et quelles sont ses limites en cas de suspicion de neuroborréliose ?","a":"<div class=\"notion-course\"><ul><li>Hors <span class=\"nc-green nc-bold\">érythème migrant</span> typique : sérologie en deux étapes avec confirmation d’un test initial positif ou douteux. <span class=\"nc-red nc-bold\">Neuroborréliose</span> : <span class=\"nc-red nc-bold\">LCS</span> et prélèvement sanguin apparié pour rechercher une synthèse intrathécale, selon délai et présentation.</li><li><span class=\"nc-brown_bg\">PCR</span> et culture ont des indications limitées et une sensibilité insuffisante pour exclure seules la maladie. Une <span class=\"nc-blue_bg\">sérologie</span> positive isolée ne démontre pas une <span class=\"nc-brown_bg\">infection active</span>.</li></ul></div>"},{"i":"62854e9fd0f9","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Sur quels critères repose le diagnostic de la maladie de Lyme ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-green nc-bold\">Érythème migrant</span> typique : diagnostic clinique, sans <span class=\"nc-red_bg nc-bold\">sérologie</span>, car celle-ci peut être <span class=\"nc-red nc-bold\">négative</span> précocement. Une fièvre ou des signes généraux n’excluent pas Lyme ; rechercher une autre infection transmise par <span class=\"nc-orange nc-bold\">tique</span> en cas de tableau atypique.</li><li>Formes disséminées : <span class=\"nc-blue_bg\">sérologie</span> en deux étapes, puis examens orientés par l’organe. <span class=\"nc-red nc-bold\">Neuroborréliose</span> : analyse du <span class=\"nc-red nc-bold\">LCS</span> et synthèse intrathécale selon délai et tableau ; arthrite : ponction pour exclure d’autres causes, avec <span class=\"nc-blue_bg\">PCR</span> ciblée si indiquée.</li><li>Une <span class=\"nc-red_bg nc-bold\">sérologie</span> positive témoigne d’un contact immunologique et ne prouve pas que des symptômes actuels sont dus à Lyme. Elle peut rester positive après guérison ; pas de contrôle sérologique pour juger l’efficacité.</li></ul></div>"},{"i":"9c60d5b88c45","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Quels sont les pièges à connaître concernant la fièvre et l'interprétation de la sérologie dans la maladie de Lyme ?","a":"<div class=\"notion-course\"><ul><li>Une fièvre n’exclut pas Lyme. Une sérologie peut rester positive après guérison ; une séropositivité chez un sujet exposé n’est pas synonyme de faux positif ni d’<span class=\"nc-brown_bg\">infection active</span>.</li><li>Pas de sérologie de dépistage chez un sujet asymptomatique ni pour contrôler l’efficacité du traitement. Un <span class=\"nc-green nc-bold\">érythème migrant</span> typique se diagnostique cliniquement.</li></ul></div>"},{"i":"71a9521e1088","n":173,"o":"173-2","u":"Étiologies","t":"Citer les principales étiologies bactériennes, virales et parasitaires des zoonoses","q":"Quels sont les points essentiels concernant citer les principales étiologies bactériennes, virales et parasitaires des zoonoses ?","a":"<div class=\"notion-course\"><p><span>Les</span> zoonoses du programme se répartissent en trois familles selon la nature de l'agent pathogène.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Zoonose</th><th>Agent</th></tr></thead>\n        <tbody>\n          <tr><td><span>Bactérienne</span></td><td><span>Fièvre</span> Q</td><td><span>Coxiella burnetii</span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td>Pasteurellose</td><td><span><span class=\"nc-purple nc-bold\">Pasteurella multocida</span></span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td><span class=\"nc-purple_bg\">Maladie des griffes du chat</span></td><td><span><span class=\"nc-purple nc-bold\">Bartonella henselae</span></span></td></tr>\n          <tr><td><span>Bactérienne</span></td><td>Borréliose de Lyme</td><td><span>Borrelia</span> (<span>spirochète</span>)</td></tr>\n          <tr><td><span>Virale</span></td><td>Rage</td><td><span>Lyssavirus</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td><span class=\"nc-orange_bg\">Toxoplasmose</span></td><td><span>Toxoplasma gondii</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td>Échinococcoses</td><td><span><span class=\"nc-purple nc-bold\">Echinococcus granulosus</span></span> ; <span>E. multilocularis</span></td></tr>\n          <tr><td><span>Parasitaire</span></td><td>Leishmaniose</td><td><span>Leishmania</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🔁 <strong>Mnémo — <span>les</span> 7 zoonoses directement transmises par un animal</strong> : « Fabrice Putain T'es Relou la ChattE » → <strong>F</strong>ièvre Q, <strong><span class=\"nc-pink nc-bold\">P</span></strong><span class=\"nc-pink nc-bold\">asteurellose</span>, <strong><span class=\"nc-orange_bg\">T</span></strong><span class=\"nc-orange_bg\">oxoplasmose</span>, <strong><span class=\"nc-green_bg\">R</span></strong><span class=\"nc-green_bg\">age</span>, <span class=\"nc-purple_bg\">maladie des griffes du </span><strong><span class=\"nc-purple_bg\">chat</span></strong>, <strong><span class=\"nc-orange_bg\">é</span></strong><span class=\"nc-orange_bg\">chinococcose hydatique</span> et alvéolaire.</div>\n      <p><strong>Bactéries potentiellement transmises par <span>morsure humaine</span></strong> : <span><span class=\"nc-purple nc-bold\">S. aureus</span></span>, <span>H. influenzae</span>, <span>Eikenella corrodens</span>, <span><span class=\"nc-purple nc-bold\">anaérobies</span></span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p></div>"},{"i":"de6a4aaec719","n":173,"o":"173-3","u":"Epidémiologie","t":"Connaître les grandes lignes de l’épidémiologie des principales zoonoses","q":"Quels sont les points essentiels concernant les grandes lignes de l’épidémiologie des principales zoonoses ?","a":"<div class=\"notion-course\"><p>L'<span>épidémiologie</span> des zoonoses se lit sur trois axes : le <strong>réservoir animal</strong>, le <strong>mode de transmission</strong> et la <strong>répartition géographique</strong>.</p>\n      <table>\n        <thead><tr><th>Zoonose</th><th>Réservoir</th><th>Transmission</th></tr></thead>\n        <tbody>\n          <tr><td>Borréliose de Lyme</td><td><span><span class=\"nc-orange nc-bold\">Tiques</span> Ixodes</span></td><td>Vecteur (<span><span class=\"nc-red_bg\">piqûre de tique</span></span>)</td></tr>\n          <tr><td>Griffes du chat</td><td><span>Chat</span> (chaton)</td><td>Inoculation (<span><span class=\"nc-blue_bg\">griffure</span></span>, <span><span class=\"nc-blue_bg\">morsure</span></span>)</td></tr>\n          <tr><td>Pasteurellose</td><td><span>Chat</span>, <span><span class=\"nc-green_bg\">chien</span></span>, <span><span class=\"nc-green_bg\">oiseaux</span></span></td><td>Inoculation (<span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>)</td></tr>\n          <tr><td><span class=\"nc-orange_bg\">Toxoplasmose</span></td><td><span>Chat</span>, <span>ruminants</span>, <span><span class=\"nc-green_bg\">porcins</span></span></td><td>Directe (litière, <span class=\"nc-red nc-bold\">viande mal cuite</span>)</td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Fièvre</span></span><span class=\"nc-purple_bg\"> Q</span></td><td><span><span class=\"nc-orange_bg\">Bovins</span></span>, <span><span class=\"nc-orange_bg\">ovins</span></span>, <span><span class=\"nc-orange_bg\">caprins</span></span></td><td>Directe (<span class=\"nc-red nc-bold\">lait cru</span>, aérosols) ou vecteur (<span>tiques</span>)</td></tr>\n          <tr><td><span class=\"nc-green_bg\">Rage</span></td><td><span><span class=\"nc-green_bg\">Canidés</span></span>, <span><span class=\"nc-green_bg\">renard</span></span>, <span>chauve-souris</span></td><td>Directe (<span><span class=\"nc-blue_bg\">morsure</span></span>, <span><span class=\"nc-blue_bg\">griffure</span></span>, <span>léchage</span>)</td></tr>\n          <tr><td>Échinococcoses</td><td><span><span class=\"nc-red nc-bold\">Chien</span></span> (hydatique) ; <span>renard</span> (alvéolaire)</td><td>Directe ou indirecte (aliments souillés)</td></tr>\n          <tr><td><span class=\"nc-pink nc-bold\">Leishmaniose</span></td><td><span>Chien</span>, <span>rongeurs</span></td><td>Vecteur (<span>phlébotome</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🎯 <strong><span>Les</span> 3 zoonoses transmises par un vecteur</strong> : <span class=\"nc-orange_bg\">leishmaniose</span> (<span><span class=\"nc-yellow_bg nc-bold\">phlébotome</span></span>), <span class=\"nc-purple_bg\">borréliose de Lyme</span> (<span><span class=\"nc-orange nc-bold\">tique</span> Ixodes</span>), <span><span class=\"nc-purple_bg\">fièvre</span></span><span class=\"nc-purple_bg\"> Q</span> (<span class=\"nc-orange nc-bold\">tiques</span>).</div>\n      <div class=\"callout callout-info\">🎯 <strong><span>Les</span> 4 zoonoses les plus fréquentes en <span class=\"nc-green_bg\">France</span> métropolitaine</strong> : <span class=\"nc-purple_bg\">borréliose de Lyme</span>, <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, <span class=\"nc-pink nc-bold\">pasteurellose</span>, <span class=\"nc-orange_bg\">toxoplasmose</span>.</div>\n      <p><span>Les</span> <strong>4 pathologies d'inoculation</strong> (transmission à travers la peau et les muqueuses) : <span class=\"nc-pink nc-bold\">borréliose de Lyme</span>, <span class=\"nc-purple_bg\">maladie des griffes du chat</span>, <span class=\"nc-pink nc-bold\">pasteurellose</span>, <span class=\"nc-pink nc-bold\">leishmaniose</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Précision sur le cycle de Lyme : les <span class=\"nc-orange nc-bold\">tiques</span> Ixodes sont les vecteurs ; les réservoirs incluent petits <span class=\"nc-yellow_bg nc-bold\">mammifères</span> et <span class=\"nc-green_bg\">oiseaux</span>. Pour la <span class=\"nc-purple_bg\">fièvre Q</span> humaine, l’inhalation d’aérosols <span class=\"nc-red nc-bold\">contaminés</span> issus d’animaux d’élevage est majeure ; ne pas la présenter comme une infection habituellement transmise par <span class=\"nc-red_bg\">piqûre de tique</span>.</li></ul></div></div>"},{"i":"1ae918ccea55","n":173,"o":"173-7","u":"Physiopathologie","t":"Connaître les phases évolutives de la maladie de Lyme","q":"Quels sont les points essentiels concernant les phases évolutives de la maladie de Lyme ?","a":"<div class=\"notion-course\"><p>L'<span>évolution</span> de la maladie de Lyme se déroule classiquement en <strong>trois phases</strong>. La majorité des diagnostics est posée à la phase primaire ; mais l'<span><span class=\"nc-green nc-bold\">érythème migrant</span></span> étant <strong><span class=\"nc-red nc-bold\">inconstant</span></strong>, <span>les</span> phases disséminées peuvent révéler la maladie.</p>\n      <table>\n        <thead><tr><th>Phase</th><th>Délai</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Localisée précoce (primaire)</td><td><span>3-30 j</span> après la piqûre</td><td><span><span class=\"nc-green nc-bold\">Érythème migrant</span></span> <span class=\"nc-red nc-bold\">inconstant</span> ; multiplication de la bactérie dans le derme</td></tr>\n          <tr><td>Disséminée précoce</td><td><span><span class=\"nc-pink nc-bold\">&lt; 6 mois</span></span></td><td><span class=\"nc-red nc-bold\">Dissémination par voie hématogène</span> :<br><strong>Neurologique :</strong> <span><span class=\"nc-yellow_bg\">méningoradiculite</span></span> ; <span>méningite</span> ; (rarement) <span><span class=\"nc-orange_bg\">encéphalite</span></span> ou <span>myélite</span><br><strong>Articulaire :</strong> <span>oligoarthrite des grosses articulations</span> (<span class=\"nc-blue nc-bold\">genou</span>)<br><strong><span class=\"nc-brown nc-bold\">Cardiaque</span> :</strong> <span>myocardite</span> ; <span>troubles de conduction</span> (BAV) fluctuants<br><strong>Cutanée :</strong> <span>lymphocytome borrélien</span><br><strong>Ophtalmologique :</strong> <span>uvéites</span></td></tr>\n          <tr><td>Disséminée tardive (tertiaire)</td><td><span><span class=\"nc-pink nc-bold\">&gt; 6 mois</span></span></td><td>Mécanisme immunologique probable :<br><strong><span class=\"nc-brown nc-bold\">Cutanée</span> :</strong> <span>acrodermatite chronique atrophiante</span><br><strong>Neurologique :</strong> <span>polyneuropathie sensitive</span> ; <span>encéphalomyélite chronique</span><br><strong>Articulaire :</strong> <span><span class=\"nc-orange_bg\">mono ou oligo-arthrite chronique</span></span></td></tr>\n        </tbody>\n      </table>\n      \n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span>Paralysie faciale</span></em></p></div>"},{"i":"7c4a6b26d9d8","n":173,"o":"173-9","u":"Prise en charge","t":"Maladie de Lyme : connaître les principes de prise en charge phase primaire","q":"Quels sont les points essentiels concernant maladie de Lyme : connaître les principes de prise en charge phase primaire ?","a":"<div class=\"notion-course\"><ul><li>Lyme : antibiothérapie selon manifestation et âge. Recommandations 2025 : <span class=\"nc-green nc-bold\">érythème migrant</span> unique, <span class=\"nc-pink nc-bold\">doxycycline</span> dix jours ; érythèmes multiples, quatorze jours. <span class=\"nc-pink_bg\">Amoxicilline</span> quatorze jours en alternative et première intention chez l’enfant de moins de 20 kg.</li><li>L’interdiction générale de <span class=\"nc-pink nc-bold\">doxycycline</span> avant huit ans est dépassée pour certaines cures courtes ; grossesse et enfant requièrent le choix précis recommandé. Les formes neurologiques, articulaires et cardiaques ont leurs propres schémas.</li><li>Retrait mécanique rapide d’une tique, désinfection, surveillance de la zone et des symptômes. Pas de <span class=\"nc-red_bg nc-bold\">sérologie</span> ni d’antibioprophylaxie systématique après une simple piqûre en <span class=\"nc-green_bg\">France</span>.</li><li>Persistance de symptômes : réévaluer diagnostic et séquelles ; pas de répétition indéfinie d’antibiotiques sans <span class=\"nc-brown_bg\">infection active</span> documentée. Les autres zoonoses requièrent des traitements adaptés à leur agent.</li></ul></div>"},{"i":"1afe39d67b6e","n":173,"o":"173-11","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la fièvre Q","q":"Quels sont les points essentiels concernant les éléments du diagnostic clinique et biologique de la fièvre Q ?","a":"<div class=\"notion-course\"><p>La <span>fièvre Q</span> est une zoonose <span>bactérienne</span> due à <span>Coxiella burnetii</span>, bactérie <span>intracellulaire</span>.</p>\n      <table>\n        <tbody>\n          <tr><td>Réservoir</td><td>Placentas des animaux infectés — surtout <span>les</span> <span><span class=\"nc-green_bg\">ruminants</span></span> (<span><span class=\"nc-green_bg\">bovins</span></span>, <span><span class=\"nc-green_bg\">ovins</span></span>, <span><span class=\"nc-green_bg\">caprins</span></span>)</td></tr>\n          <tr><td>Transmission</td><td><strong>Inhalée :</strong> aérosols de <span class=\"nc-red nc-bold\">paille</span> et de <span class=\"nc-red nc-bold\">fumier</span> <span class=\"nc-red nc-bold\">contaminés</span> ; <br><strong>Digestive :</strong> consommation de <span class=\"nc-red nc-bold\">lait cru</span> ; <br><strong>Vecteur :</strong> <span class=\"nc-brown_bg\">tiques</span></td></tr>\n        </tbody>\n      </table>\n      <p>Infection <span><span class=\"nc-pink nc-bold\">asymptomatique</span> dans 60 %</span> des cas. Trois formes cliniques :</p>\n      <table>\n        <thead><tr><th>Forme</th><th>Caractéristiques</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Aiguë (la plus fréquente)</td><td><span class=\"nc-yellow_bg\">Incubation</span> ~<span><span class=\"nc-pink nc-bold\">3 semaines</span></span>, début pseudo-grippal, puis <span><span class=\"nc-blue_bg\">fièvre</span></span><span class=\"nc-blue_bg\"> isolée</span>, <strong><span><span class=\"nc-red nc-bold\">hépatite</span></span><span class=\"nc-red nc-bold\"> fébrile</span></strong> <span class=\"nc-red_bg\">(présentation la plus fréquente)</span> ou pneumopathie interstitielle</td><td><span><span class=\"nc-pink_bg\">Doxycycline</span></span> pendant <span><span class=\"nc-pink nc-bold\">2 à 3 semaines</span></span></td></tr>\n          <tr><td>Chronique</td><td><span>Terrain</span> : immunodéprimé, porteur de <span>lésion</span> valvulaire ou vasculaire → <span>endocardite à hémocultures négatives</span>, <span class=\"nc-red_bg\">infection vasculaire</span> (<span class=\"nc-pink nc-bold\">anévrisme</span>, prothèse)</td><td><span><span class=\"nc-pink_bg\">Doxycycline</span> + <span class=\"nc-pink_bg\">hydroxychloroquine</span></span>, durée prolongée (<span>18 à 24 mois</span>)</td></tr>\n          <tr><td>Femme enceinte</td><td>Conséquences fœtales (fausses couches)</td><td><span>Cotrimoxazole</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations biologiques</strong> : <span><span class=\"nc-blue_bg\">thrombopénie</span></span>, <span><span class=\"nc-blue_bg\">leuco-neutropénie</span></span> possible, <span><span class=\"nc-blue_bg\">cytolyse hépatique</span></span>, allongement du <span>TCA</span> (<span>anticoagulant</span> circulant).</p>\n      <p><strong>Microbiologie</strong> : <span><span class=\"nc-blue_bg\">sérologie</span></span> de <em>Coxiella burnetii</em> — le type d'anticorps identifié oriente vers une forme chronique ; <span><span class=\"nc-brown_bg\">PCR</span></span> et culture possibles en centre de référence.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span>Endocardite</span> infectieuse</em></p></div>"},{"i":"88eb8bb7036f","n":173,"o":"173-13","u":"Prise en charge","t":"Connaître les situations à risque et les principes de la prise en charge","q":"Quels sont les points essentiels concernant les situations à risque et les principes de la prise en charge ?","a":"<div class=\"notion-course\"><ul><li>Après exposition rabique possible : lavage eau–savon pendant quinze minutes puis antisepsie. Évaluer l’animal, le pays, le type de contact et la vaccination antérieure ; consulter rapidement un centre antirabique.</li><li>La prophylaxie associe vaccin et, dans certaines expositions, immunoglobulines. Son schéma dépend du protocole et de l’immunisation antérieure ; la série « J0, J3, J7, J14, J15 » de l’ancienne fiche est erronée.</li><li>Une vaccination pré-exposition ne dispense pas de consultation ni de rappels après exposition. Ne pas attendre les symptômes, après lesquels la maladie est presque toujours mortelle.</li><li>Chauves-souris, exposition en zone d’endémie ou animal récemment importé : situations particulièrement importantes. La seule absence de certificat vaccinal d’un animal ne suffit pas à définir le risque ; l’évaluation est spécialisée.</li></ul></div>"},{"i":"098d8e2d5c75","n":173,"o":"173-16","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunodéprimé + femme enceinte","q":"Quels sont les points essentiels concernant les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunodéprimé + femme enceinte ?","a":"<div class=\"notion-course\"><ul><li>Toxoplasmose chez l’immunodéprimé : réactivation fréquente, notamment cérébrale ; déficit focal, crises ou <span class=\"nc-blue_bg\">céphalées</span> imposent imagerie et diagnostic différentiel. Une <span class=\"nc-red_bg nc-bold\">sérologie</span> <span class=\"nc-red nc-bold\">négative</span> rend la réactivation moins probable sans exclure toute toxoplasmose.</li><li>VIH : cotrimoxazole en première intention des recommandations HAS 2024, traitement d’attaque six semaines puis entretien ; <span class=\"nc-pink_bg\">pyriméthamine</span>–<span class=\"nc-pink_bg\">sulfadiazine</span>–<span class=\"nc-green_bg\">acide</span> <span class=\"nc-green_bg nc-bold\">folinique</span> est une alternative. Surveiller réponse clinique/radiologique et toxicité.</li><li>Grossesse : dater et confirmer une infection maternelle par expertise sérologique ; organiser traitement et diagnostic prénatal avec une équipe spécialisée. Risque de transmission croissant avec le terme, gravité fœtale généralement plus importante si infection précoce.</li><li>PCR sur liquide amniotique selon terme et délai après infection ; un résultat négatif n’exclut pas toutes les infections tardives. Le <span class=\"nc-blue_bg nc-bold\">nouveau-né</span> exposé nécessite un bilan et un suivi spécifiques.</li></ul></div>"},{"i":"b60404a2c1e6","n":173,"o":"173-17","u":"Étiologies","t":"Connaître les espèces à l’origine des deux formes d’échinococcose","q":"Quels sont les points essentiels concernant les espèces à l’origine des deux formes d’échinococcose ?","a":"<div class=\"notion-course\"><p>L'<span>échinococcose</span> existe sous deux formes, dues à deux espèces distinctes du genre <span>Echinococcus</span> (<span>cestodes / ténias</span> — plathelminthes segmentés).</p>\n      <table>\n        <thead><tr><th></th><th><span class=\"nc-orange_bg\">Échinococcose hydatique</span></th><th><span class=\"nc-orange_bg\">Échinococcose alvéolaire</span></th></tr></thead>\n        <tbody>\n          <tr><td>Agent</td><td><span><span class=\"nc-purple nc-bold\">Echinococcus granulosus</span></span></td><td><span><span class=\"nc-purple nc-bold\">Echinococcus multilocularis</span></span></td></tr>\n          <tr><td>Hôte définitif</td><td><strong><span>Chien</span></strong></td><td><strong><span><span class=\"nc-red nc-bold\">Renard</span></span></strong>, <span>chien</span></td></tr>\n          <tr><td>Hôte intermédiaire</td><td><span><span class=\"nc-yellow_bg nc-bold\">Mouton</span></span></td><td><span>Rongeurs</span></td></tr>\n          <tr><td>Géographie</td><td>Parasitose <span><span class=\"nc-red nc-bold\">cosmopolite</span></span> : régions d'élevage (Maghreb, <span class=\"nc-green_bg\">sud de la France</span>)</td><td>Nord et centre de l'Europe (Vosges, Jura, Alpes, Massif central)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans <span>les</span> deux cas, l'<strong><span class=\"nc-yellow_bg\">homme est un </span><span><span class=\"nc-yellow_bg\">hôte accidentel</span></span></strong> (impasse <span>parasitaire</span>), contaminé par <span>contact</span> direct avec l'hôte définitif ou indirectement via des aliments, l'<span class=\"nc-red nc-bold\">eau</span> ou des objets souillés par les déjections.</p></div>"},{"i":"d013ac5036f5","n":173,"o":"173-18","u":"Diagnostic positif","t":"Connaître les localisations préférentielles des échinococcoses","q":"Quels sont les points essentiels concernant les localisations préférentielles des échinococcoses ?","a":"<div class=\"notion-course\"><p><span>Les</span> deux échinococcoses ont des <strong>localisations préférentielles</strong> distinctes.</p>\n      <p><strong><span class=\"nc-orange_bg\">Échinococcose hydatique</span> (kyste hydatique)</strong> — l'œuf embolise le système circulatoire au niveau du <span class=\"nc-purple_bg\">tube digestif</span>, puis se fixe :</p>\n      <table>\n        <thead><tr><th>Localisation</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span>Foie</span></td><td><span>50-60 %</span></td></tr>\n          <tr><td><span>Poumon</span></td><td><span>30-40 %</span></td></tr>\n          <tr><td><span class=\"nc-blue_bg\">Autres organes</span></td><td><span>10 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le plus souvent <span><span class=\"nc-pink nc-bold\">asymptomatique</span></span> (découverte fortuite à l'imagerie) : <span>hépatomégalie</span> isolée <span><span class=\"nc-blue_bg\">indolore</span></span> pour la forme hépatique ; <span><span class=\"nc-blue_bg\">toux</span></span>, <span><span class=\"nc-blue_bg\">dyspnée</span></span>, <span><span class=\"nc-blue_bg\">hémoptysie</span></span> pour la forme pulmonaire. À l'<span>imagerie</span>, le kyste peut prendre l'aspect d'un kyste biliaire simple, d'une <span>paroi calcifiée</span> (kyste mort), ou d'une <span>membrane décollée ou flottante</span>.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong><span>Drapeau rouge</span>.</strong> La <span>ponction d'un kyste hydatique est formellement contre-indiquée</span> — <span class=\"nc-red nc-bold\">risque de </span><span><span class=\"nc-red nc-bold\">dissémination intrapéritonéale</span></span> et de réaction anaphylactique. Aucune image kystique intrahépatique ne se ponctionne sans <span><span class=\"nc-blue_bg\">sérologie</span></span> préalable.</div>\n      <p><strong><span class=\"nc-orange_bg\">Échinococcose alvéolaire</span></strong> — localisation <strong>intra-hépatique</strong> : <span>masse hépatique pseudo-tumorale infiltrante</span>, <span>mimant une néoplasie</span> à l'imagerie ; complications par <span>compression des voies biliaires</span> et des organes adjacents.</p>\n      \n      \n      <div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La ponction diagnostique non préparée d’un kyste suspect d’hydatidose est à proscrire. Cela n’interdit pas la technique thérapeutique spécialisée PAIR dans certaines formes sélectionnées, avec précautions et couverture antiparasitaire. Une calcification ne prouve pas à elle seule que tout le kyste est inactif.</li></ul></div></div>"},{"i":"958c18da998a","n":173,"o":"173-19","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic de leishmaniose cutanée","q":"Quels sont les points essentiels concernant évoquer le diagnostic de leishmaniose cutanée ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-orange_bg\">leishmaniose</span></span> est une parasitose due à un protozoaire du genre <span>Leishmania</span>.</p>\n      <table>\n        <tbody>\n          <tr><td>Vecteur</td><td>Insecte piqueur nocturne — le <span><span class=\"nc-yellow_bg nc-bold\">phlébotome</span></span></td></tr>\n          <tr><td>Réservoir</td><td><span>Chien</span>, <span><span class=\"nc-blue_bg\">rongeurs</span></span>, <span>homme</span></td></tr>\n          <tr><td>Géographie</td><td><span class=\"nc-green_bg\">Pourtour méditerranéen</span> (<span class=\"nc-green_bg\">France</span>) et zones tropicales (voyageurs)</td></tr>\n          <tr><td>Incubation</td><td><span><span class=\"nc-pink nc-bold\">Plusieurs semaines</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Leishmaniose cutanée</strong> — à évoquer devant une <span>lésion</span> sur une <strong>zone découverte</strong>, évoluant en trois temps :</p>\n      <ol>\n        <li>Une <span>papule carmin</span> infiltrée, initialement.</li>\n        <li>Puis une <span>ulcération secondaire avec croûte</span>, <span class=\"nc-blue_bg\">entourée d'un bourrelet rouge</span>, <strong><span><span class=\"nc-blue_bg\">indolore</span></span></strong>.</li>\n        <li><span><span class=\"nc-orange_bg\">Évolution</span></span><span class=\"nc-orange_bg\"> </span><span><span class=\"nc-orange_bg\">chronique</span></span> sur plusieurs mois.</li>\n      </ol>\n      \n      \n      <p><strong>Diagnostic</strong> : <span>examen direct</span> sur frottis de grattage du pourtour de la <span>lésion</span> ou <span><span class=\"nc-blue_bg\">biopsie</span></span> ; <span><span class=\"nc-blue_bg\">PCR</span></span> sur la peau.</p>\n      <div class=\"callout callout-info\">Pour contraste : la <strong><span class=\"nc-orange_bg\">leishmaniose</span> viscérale</strong> (kala-azar), plus rare et touchant l'<span class=\"nc-red nc-bold\">enfant</span> ou l'<span class=\"nc-red nc-bold\">immunodéprimé</span>, associe <span><span class=\"nc-yellow_bg\">fièvre</span></span><span class=\"nc-yellow_bg\"> hectique</span>, <span><span class=\"nc-blue_bg\">splénomégalie</span></span> et <span>pancytopénie</span> ; son diagnostic repose sur le <span>myélogramme</span> et la <span><span class=\"nc-blue_bg\">sérologie</span></span>.</div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d9418174a2eac5a57f8bb35e?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
